/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A27: downwelling–drinking (20/80 frozen manifest). */
'use strict';
const D = globalThis.RA.D;
const q = (w,n,s,prompt,options,answer,explain) => ({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt,options,answer,explain});
const c = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const put = (w,origin,context,wrong,right,reason,quiz) => D(w,{etymology:{origin,source:'conservative word-history note'},contexts:[context],mistakes:[{errorType:'meaning',wrong,right,reason}],quiz});

put('downwelling','downwelling 是 down 与 welling（well「涌动」的 -ing 形式）组成的海洋学复合词，指表层海水向较深水层下沉；这属于透明构词说明。',c('downwelling.s1','海洋环流','Coastal winds pushed surface water offshore, so colder water sank in a broad zone of downwelling and carried dissolved oxygen into deeper layers.','沿岸风把表层水推向外海，因此一大片海域出现下降流，将溶解氧带入更深水层。','Coastal winds pushed surface water offshore / so colder water sank in a broad zone of downwelling / and carried dissolved oxygen into deeper layers.','downwelling 是介词 of 的宾语；so 引出表层水下沉的结果。','水体由表层沉向深层，正是海洋学的 downwelling。'),'Downwelling describes warm deep water rising to replace surface water.','Upwelling describes deep water rising to replace surface water; downwelling is the sinking of surface water.','上升流是深水上涌；downwelling 的方向相反，是表层水下沉。',[q('downwelling',1,1,'In oceanography, downwelling is the movement of surface water?',['down into deeper layers','up from the seabed to the surface','sideways onto dry land'],'down into deeper layers','downwelling.s1 指表层海水向深层下沉。'),q('downwelling',2,1,'Which condition can help drive coastal downwelling?',['winds that push surface water toward shore','a river flowing uphill','a tide that removes all seawater'],'winds that push surface water toward shore','沿岸风把表层水推向岸边时，水可向下沉降。'),q('downwelling',3,1,'What may downwelling transport from the surface?',['oxygen-rich water into deeper ocean layers','sand from a desert onto a mountain','sunlight into the ocean floor'],'oxygen-rich water into deeper ocean layers','下沉水流可把含氧表层水带入深层。'),q('downwelling',4,1,'Which process is the opposite vertical direction from downwelling?',['upwelling, in which deep water rises','evaporation from a puddle','rain falling through the atmosphere'],'upwelling, in which deep water rises','upwelling 是深水上升，与 downwelling 的下沉相反。')]);

put('downwind','downwind 是 down 与 wind 构成的方向词，按风吹去的方向理解；副词和形容词用法分别对应移动方向与所处方位。',c('downwind.s1','野外安全','The ranger kept the cooking fire downwind of the tents, so smoke travelled away from the sleeping area instead of blowing into it.','护林员把炊火设在帐篷的下风处，因此烟飘离睡眠区，没有吹进帐篷。','The ranger kept the cooking fire downwind of the tents / so smoke travelled away from the sleeping area / instead of blowing into it.','downwind of 表示位于某物的下风处；instead of 对比烟的去向。','火在帐篷的下风侧，体现 downwind.s2 的位置形容词用法。'),'We camped downwind of the fire so the smoke blew directly toward our faces.','We camped upwind of the fire so the smoke blew away from our faces.','如果烟迎面吹来，人应在火的上风处；downwind 意为顺着风吹去的一侧。',[q('downwind',1,1,'If smoke travels downwind, it moves?',['in the direction the wind is blowing','against the wind','straight upward regardless of wind'],'in the direction the wind is blowing','downwind.s1 是顺着风吹去的方向。'),q('downwind',2,2,'A downwind campsite is located?',['on the side toward which the wind blows','on the side from which the wind comes','under the ground'],'on the side toward which the wind blows','作形容词时，downwind 指位于下风的一侧。'),q('downwind',3,1,'A factory smell reaches a village downwind. The village is?',['in the path the air carries the smell','upwind and isolated from the air flow','inside the factory chimney'],'in the path the air carries the smell','气味顺风飘向村庄，村庄处在气流去向一侧。'),q('downwind',4,2,'Which phrase correctly describes the side of a boat where the wind is blowing toward?',['the downwind side','the upwind side','the windless side'],'the downwind side','风吹去的一侧称 downwind side。')]);

put('drab','drab 的历史来源不够确定，现代英语把它作为独立形容词使用；它既可形容缺乏生气，也可指暗淡的浅棕色，不强行拆分词根。',c('drab.s2','服饰与色彩','The artist used a drab brown for the old coat, then added a bright red scarf so the figure would stand out against the grey wall.','画家把旧外套画成暗淡的浅棕色，随后添上鲜红围巾，让人物在灰墙前更醒目。','The artist used a drab brown for the old coat / then added a bright red scarf / so the figure would stand out against the grey wall.','drab 修饰 brown，作颜色形容词；so 从句说明添亮色的目的。','drab brown 明确表示暗淡的浅棕色，属于 drab.s2。'),'The drab blue paint was intensely bright and vivid, so it lit up the whole room.','The vivid blue paint was intensely bright and lit up the whole room.','鲜亮的颜色与 drab 所含的暗淡、不鲜明相矛盾。',[q('drab',1,1,'A drab routine is one that feels?',['dull and lacking excitement','full of cheerful variety','dangerously fast'],'dull and lacking excitement','drab.s1 指乏味、缺少趣味或生气。'),q('drab',2,2,'A drab coat described by its colour is likely?',['a dull light brown','bright turquoise','pure scarlet'],'a dull light brown','drab.s2 指暗淡的浅棕色。'),q('drab',3,1,'Which setting would a writer most naturally call drab?',['a grey office with no decoration and little activity','a lively festival full of music and colour','a sunny garden in full bloom'],'a grey office with no decoration and little activity','沉闷单调的环境符合 drab.s1。'),q('drab',4,2,'The painter chose a drab shade for the canvas. What quality did the shade have?',['it was muted rather than bright','it glowed like a neon sign','it was transparent and colourless'],'it was muted rather than bright','形容颜色时 drab 表示灰暗、不鲜亮。')]);

put('dragonfly','dragonfly 是 dragon 与 fly 构成的复合名词；这里的 fly 指双翅昆虫，词名不表示它是龙或普通家蝇。',c('dragonfly.s1','池塘生态','A dragonfly hovered above the pond, its transparent wings beating rapidly as it hunted small insects near the reeds.','一只蜻蜓在池塘上方盘旋，透明翅膀快速振动，捕食芦苇附近的小昆虫。','A dragonfly hovered above the pond / its transparent wings beating rapidly / as it hunted small insects near the reeds.','dragonfly 是句子主语；as 引出盘旋时捕食的伴随情景。','透明翅、细长体形和水边捕食场景对应蜻蜓这一昆虫义。'),'The dragonfly is a large reptile that crawls on dry land and has no wings.','The dragonfly is a flying insect with two pairs of wings, often found near water.','蜻蜓是有翅昆虫，不是爬行动物。',[q('dragonfly',1,1,'Which description identifies a dragonfly?',['a slender flying insect with two pairs of clear wings','a flightless reptile with scales','a small mammal that lives underground'],'a slender flying insect with two pairs of clear wings','dragonfly.s1 是有两对薄翅的飞行昆虫。'),q('dragonfly',2,2,'A dragonfly nymph differs from an adult because the nymph?',['is the aquatic immature stage','is a fully grown bird','is a flower growing beside water'],'is the aquatic immature stage','dragonfly.s2 指蜻蜓成虫；幼体通常是水生阶段。'),q('dragonfly',3,1,'Where would a naturalist most likely watch dragonflies hunting?',['beside a pond or slow stream','inside a sealed oven','on a snow-covered glacier far from water'],'beside a pond or slow stream','蜻蜓常在水边活动并捕食小昆虫。'),q('dragonfly',4,1,'The name dragonfly refers to an insect, not to?',['a mythical fire-breathing dragon','a winged insect','an animal with a long body'],'a mythical fire-breathing dragon','dragonfly 是昆虫名称，不能按 dragon 的字面神话义理解。')]);

put('drainage','drainage 由 drain 加名词后缀 -age 构成，可指排水的过程，也可指实施排水的管沟系统。',c('drainage.s1','城市工程','After heavy rain flooded the underpass, engineers widened the drainage channels and cleared leaves from the grates to let runoff escape.','暴雨淹没下穿通道后，工程师拓宽排水沟渠，并清走格栅上的树叶以便径流排出。','After heavy rain flooded the underpass / engineers widened the drainage channels / and cleared leaves from the grates / to let runoff escape.','drainage 修饰 channels，组成排水渠道；to-infinitive 表示清理的目的。','沟渠、格栅和排走径流都属于排水系统及其功能。'),'Good drainage leaves rainwater trapped on the road for several days.','Good drainage carries rainwater away from the road and prevents prolonged pooling.','排水良好应让水流走；积水久留表明排水不畅。',[q('drainage',1,1,'A field with poor drainage is likely to?',['remain waterlogged after rain','dry instantly because it has no soil','produce clean drinking water by itself'],'remain waterlogged after rain','drainage.s1 指排水；poor drainage 会造成积水。'),q('drainage',2,1,'A drainage system is designed mainly to?',['carry excess water away','pump smoke into a building','store every drop on a road'],'carry excess water away','排水系统的作用是移走多余的水。'),q('drainage',3,1,'Which change could improve drainage around a house?',['clearing a blocked gutter and downpipe','sealing every outlet with concrete','directing roof water into the basement'],'clearing a blocked gutter and downpipe','清除堵塞能恢复屋顶排水。'),q('drainage',4,1,'The drainage of a marsh refers to?',['the removal of water from the land','the planting of trees in dry soil','the measurement of wind speed'],'the removal of water from the land','drainage 也可指把一片土地的水排走这一过程。')]);

put('drainpipe','drainpipe 是 drain 与 pipe 的透明复合词，指把屋顶、洗涤槽或排水口的水导走的管道。',c('drainpipe.s1','房屋维护','A loose drainpipe spilled roof water against the brick wall, so the caretaker fixed its bracket and directed the outlet toward the garden drain.','一根松脱的排水管把屋顶水洒在砖墙上，因此管理员固定了管箍，并把出口朝向花园排水口。','A loose drainpipe spilled roof water against the brick wall / so the caretaker fixed its bracket / and directed the outlet toward the garden drain.','drainpipe 是 spilled 的主语；so 引出维修措施。','屋顶雨水经管道被导向排水口，符合 drainpipe.s1。'),'The drainpipe sent rain from the roof up into the attic and kept it there.','The drainpipe carried rain from the roof down to a drain away from the wall.','排水管把水导离屋顶和墙面，不会把雨水送入阁楼蓄存。',[q('drainpipe',1,1,'A drainpipe on a house usually carries?',['rainwater from the roof toward a drain','fresh air into a chimney','electricity from a socket'],'rainwater from the roof toward a drain','drainpipe.s1 指输送排水的管子。'),q('drainpipe',2,1,'Water pouring down the outside wall may indicate that a drainpipe is?',['blocked, broken, or disconnected','working perfectly underground','being used as a window'],'blocked, broken, or disconnected','管道异常会使屋顶水溅到墙面。'),q('drainpipe',3,1,'Which repair addresses a loose drainpipe?',['secure its bracket to the wall','remove the roof gutter and block the outlet','paint a nearby door'],'secure its bracket to the wall','固定支架可让排水管保持连接和导流。'),q('drainpipe',4,1,'A drainpipe differs from a drinking-water pipe because it normally?',['takes unwanted water away','supplies water for cooking','measures the height of a roof'],'takes unwanted water away','drainpipe 的功能是排走多余的水。')]);

put('drake','drake 是表示成年雄鸭的独立名词；它不是所有鸭子的泛称，也不等同于雌鸭或幼鸭。',c('drake.s1','鸟类观察','The drake’s iridescent green head made it easy to distinguish from the brown female mallards swimming beside the reeds.','这只公鸭的头部闪着虹彩般的绿色，因此很容易与芦苇旁游动的棕色母野鸭区分开。','The drake’s iridescent green head made it easy to distinguish / from the brown female mallards / swimming beside the reeds.','drake’s 是名词所有格，修饰 head；from 短语指出比较对象。','成年雄鸭的羽色特征与雌鸭作对比，清楚呈现 drake.s1。'),'The drake laid the eggs while the female duck guarded the nest.','The female duck laid the eggs while the drake guarded the nearby water.','通常产卵的是雌鸭；drake 指成年雄鸭。',[q('drake',1,1,'A drake is an adult?',['male duck','female swan','young goose'],'male duck','drake.s1 的定义是成年雄鸭。'),q('drake',2,1,'In a flock, a drake can be distinguished from a hen by being?',['male rather than female','a fish rather than a bird','a nest rather than an animal'],'male rather than female','drake 与母鸭相对，特指雄鸭。'),q('drake',3,1,'A wildlife note says “one drake and three hens.” How many male ducks are counted?',['one','three','four'],'one','drake 表示雄鸭，所以有一只雄鸭。'),q('drake',4,1,'Which sentence uses drake accurately?',['The drake swam behind the female mallards.','The drake incubated her eggs as a female goose.','The drake is the name of a pond plant.'],'The drake swam behind the female mallards.','drake 是雄鸭名词，第一句使用正确。')]);

put('dramatic','dramatic 经由 drama 加形容词后缀 -ic 构成；既可指突然而显著的变化，也可指戏剧般生动、富有表现力。',c('dramatic.s1','气候记录','The region experienced a dramatic drop in temperature overnight, with the morning forecast nearly twenty degrees colder than the previous day.','该地区夜间气温骤降，早间预报比前一天低了近二十度。','The region experienced a dramatic drop in temperature overnight / with the morning forecast nearly twenty degrees colder / than the previous day.','dramatic 修饰 drop，强调变化幅度大且醒目；with 短语补充量化结果。','近二十度的明显骤降体现 dramatic.s1。'),'The temperature made a dramatic change of only one hundredth of a degree, too small to notice.','The temperature made a slight change of only one hundredth of a degree, too small to notice.','几乎察觉不到的微小变化不能称为 dramatic 的显著变化。',[q('dramatic',1,1,'A dramatic increase in sales is?',['large and striking','small and barely noticeable','a kind of stage curtain'],'large and striking','dramatic.s1 表示变化显著、幅度大。'),q('dramatic',2,2,'A dramatic reading of a poem would be?',['vivid and expressive, like a performance','flat, inaudible, and without expression','a calculation of rainfall'],'vivid and expressive, like a performance','dramatic.s2 指像戏剧表演一样生动。'),q('dramatic',3,1,'Which event is most naturally called dramatic?',['a sudden fall in the river level after a dam opens','a barely measurable daily fluctuation','a routine entry in a calendar'],'a sudden fall in the river level after a dam opens','突然而明显的变化符合 dramatic.s1。'),q('dramatic',4,2,'An actor gives a dramatic pause to?',['heighten the scene’s effect','hide the stage from every viewer','measure the length of the script'],'heighten the scene’s effect','戏剧化的停顿增强舞台表现效果。')]);

put('dramatically','dramatically 是 dramatic 加副词后缀 -ally；可修饰显著变化，也可说明动作像舞台表演般夸张。',c('dramatically.s1','统计报告','After the city introduced reliable bus service, the number of households using private cars to commute fell dramatically over the next three years.','市里开通可靠的公交服务后，接下来三年里开车通勤的家庭数量大幅下降。','After the city introduced reliable bus service / the number of households using private cars to commute fell dramatically / over the next three years.','dramatically 修饰 fell，说明下降幅度大；after 引导时间背景。','通勤家庭数量大幅下降，体现 dramatically.s1。'),'The rate changed dramatically by just 0.001 percent, an amount no observer could detect.','The rate changed slightly by just 0.001 percent, an amount no observer could detect.','几乎无法察觉的微变应称 slightly，而非 dramatically。',[q('dramatically',1,1,'If costs fall dramatically, they fall?',['by a large and noticeable amount','by an amount too tiny to detect','only in a theatrical costume'],'by a large and noticeable amount','dramatically.s1 表示显著、大幅度地。'),q('dramatically',2,2,'An actor who dramatically throws up her hands does so?',['in an exaggerated, theatrical way','quietly and without visible movement','according to a mathematical ratio'],'in an exaggerated, theatrical way','dramatically.s2 指像戏剧表演般夸张地。'),q('dramatically',3,1,'Which report best supports the adverb dramatically?',['Emissions dropped by half in one year.','Emissions changed by an unmeasurable trace.','No emissions data were collected.'],'Emissions dropped by half in one year.','减半是醒目的大幅变化，符合该副词的程度义。'),q('dramatically',4,2,'A person reacts dramatically to a minor delay by?',['gasping, clutching the chest, and making a scene','checking the clock calmly and waiting','quietly reading a book'],'gasping, clutching the chest, and making a scene','小事引发夸张舞台式反应，符合 dramatically.s2。')]);

put('dramatist','dramatist 由 drama 加表示人的后缀 -ist 构成，指创作戏剧、剧本或舞台作品的作者。',c('dramatist.s1','文学史','The dramatist adapted a family’s letters into a stage play, giving each generation a distinct voice while preserving the dates and major events.','这位剧作家把一个家庭的书信改编成舞台剧，在保留日期和重大事件的同时，为每一代人塑造了不同的声音。','The dramatist adapted a family’s letters into a stage play / giving each generation a distinct voice / while preserving the dates and major events.','dramatist 是 adapted 的主语；while 引出创作时兼顾的另一项要求。','创作舞台剧的作者就是 dramatist.s1。'),'The dramatist designed only the theatre’s heating pipes and never wrote or adapted a play.','The stage director designed the theatre’s heating system; the dramatist wrote or adapted the play.','dramatist 是剧作家，不是负责剧院设施设计的工程师。',[q('dramatist',1,1,'A dramatist is chiefly a person who?',['writes plays for the stage','repairs theatre lighting cables','reviews restaurant menus'],'writes plays for the stage','dramatist.s1 指戏剧作者。'),q('dramatist',2,1,'A historian turns a diary into a stage script. The person doing the adaptation is acting as a?',['dramatist','ticket inspector','stage curtain'],'dramatist','把材料改编成剧本属于剧作家的工作。'),q('dramatist',3,1,'Which credit would most likely appear beside a dramatist’s name?',['Written by','Sound equipment repaired by','Seats counted by'],'Written by','剧作家负责写作，通常获得 Written by 的署名。'),q('dramatist',4,1,'A dramatist differs from an actor because the dramatist usually?',['creates the play’s script','performs every role on stage','sells all the theatre tickets'],'creates the play’s script','dramatist 创作剧本；演员负责表演角色。')]);

put('dramatization','dramatization 是 dramatize 加名词后缀 -ation，可指把书籍或真实事件改编成剧，也可指对事实作戏剧化渲染。',c('dramatization.s1','影视改编','The radio dramatization of the explorer’s journals used several actors and sound effects, but the narrator explained which scenes had been invented.','这部探险家日记的广播剧改编使用了多位演员和音效，不过旁白说明了哪些场景是虚构的。','The radio dramatization of the explorer’s journals used several actors and sound effects / but the narrator explained / which scenes had been invented.','dramatization 是主语中心词；of 短语说明改编来源，but 引出对虚构内容的提示。','广播节目把日记改编成戏剧作品，符合 dramatization.s1。'),'The radio dramatization reproduced every journal entry as an unchanged photocopy and contained no performance.','The radio dramatization turned the journal entries into a performed audio story.','没有表演或改编的原样复印件不构成广播剧改编。',[q('dramatization',1,1,'A dramatization of a memoir is?',['a play or film adapted from the memoir','a list of the memoir’s page numbers','a factual correction with no presentation'],'a play or film adapted from the memoir','dramatization.s1 指改编作品。'),q('dramatization',2,2,'A journalist accuses a report of dramatization. The concern is that it?',['makes events seem more exciting than the facts justify','omits every dramatic scene from a play','is a verb tense error'],'makes events seem more exciting than the facts justify','dramatization.s2 可指夸张渲染事实。'),q('dramatization',3,1,'A novel is adapted into a stage production. The new production is a?',['dramatization','drainage system','dramatic pause'],'dramatization','将小说改编成舞台剧即一种 dramatization。'),q('dramatization',4,2,'Which statement describes unfair dramatization of a minor incident?',['A report portrays a brief delay as a citywide crisis.','A play accurately stages a historical speech.','A script lists the actors’ names.'],'A report portrays a brief delay as a citywide crisis.','把小事夸成危机是戏剧化渲染。')]);

put('dramatize','dramatize 由 drama 加动词化后缀 -ize 构成，可把故事改编成戏剧，也可夸大事件使其显得更严重。',c('dramatize.s2','新闻写作','The editor asked the reporter not to dramatize a routine power cut as a disaster, but to state how many homes were affected and for how long.','编辑要求记者不要把一次常规停电夸成灾难，而应写清影响了多少户、持续了多久。','The editor asked the reporter not to dramatize a routine power cut as a disaster / but to state how many homes were affected / and for how long.','dramatize 是 ask + 人 + not to do 中的不定式；as 指被夸大呈现的身份。','把普通停电描写成灾难是夸大事实，符合 dramatize.s2。'),'The article dramatized the minor delay by describing it as a small, routine inconvenience.','The article described the minor delay as a small, routine inconvenience without dramatizing it.','平实地称小延误为小麻烦并没有夸大，去掉 dramatize 才准确。',[q('dramatize',1,1,'To dramatize a novel for television is to?',['adapt it into a performed screen story','remove every character and plot','measure its paper weight'],'adapt it into a performed screen story','dramatize.s1 表示改编为戏剧、影视作品。'),q('dramatize',2,2,'If a speaker dramatizes a small problem, the speaker?',['makes it seem more serious or exciting than it is','quietly corrects it with exact figures','turns it into a water pipe'],'makes it seem more serious or exciting than it is','dramatize.s2 指夸大渲染问题。'),q('dramatize',3,1,'A school stages a play based on a scientist’s life. It has dramatized the life by?',['presenting it as a drama','listing it as a phone number','burying the script unread'],'presenting it as a drama','舞台呈现传记故事是改编成戏剧。'),q('dramatize',4,2,'Which headline dramatizes a minor event?',['“One Late Bus Leaves the Entire City in Chaos”','“Bus Arrives Three Minutes Late”','“Transit Schedule for Tuesday”'],'“One Late Bus Leaves the Entire City in Chaos”','标题把一次小延误渲染成全城混乱，显然夸张。')]);

put('drapery','drapery 源于 drape（悬垂布料）加名词后缀 -ery，可泛指帷幔或形成松软褶皱的布料。',c('drapery.s1','室内设计','Heavy blue drapery framed the tall windows, and its deep folds softened the light entering the reading room.','厚重的蓝色帷幔围住高窗，深深的褶皱柔化了照进阅览室的光线。','Heavy blue drapery framed the tall windows / and its deep folds softened the light / entering the reading room.','drapery 是主语；its 指帷幔，entering 分词修饰 light。','挂在窗边并形成褶皱的厚布料是帷幔义。'),'The bare window had no hanging cloth or folds, yet the decorator called the empty wall drapery.','The decorator hung folded drapery around the window to soften the light.','空墙没有悬挂布料，不能称为 drapery。',[q('drapery',1,1,'Window drapery is typically?',['cloth hung in folds as curtains','a metal window latch','a stone floor covering'],'cloth hung in folds as curtains','drapery.s1 指帷幔、窗帘等悬垂布料。'),q('drapery',2,1,'An art student studies the drapery in a painted robe. The student studies?',['the way the cloth hangs in folds','the person’s shoe size','the colour of the gallery walls only'],'the way the cloth hangs in folds','绘画中 drapery 也可指衣料形成的褶皱。'),q('drapery',3,1,'Which item would a curtain shop sell as drapery?',['long folded fabric panels for a window','a brass door key','a ceramic dinner plate'],'long folded fabric panels for a window','窗边悬挂的布帘属于 drapery。'),q('drapery',4,1,'The sculptor carved realistic drapery around the statue’s arm. This means the sculptor showed?',['the folds and hanging form of the clothing','a drainage pipe inside the stone','the statue’s heartbeat'],'the folds and hanging form of the clothing','雕像的 drapery 指衣料垂落形成的褶皱。')]);

put('drastically','drastically 源自 drastic 加副词后缀 -ally；用来强调变化幅度极大、措施严厉或影响显著。',c('drastically.s1','预算调整','When the grant was cancelled, the museum drastically reduced its opening hours and postponed two exhibitions rather than close the collection entirely.','拨款取消后，博物馆大幅缩短开放时间并推迟两场展览，而没有彻底关闭藏品展厅。','When the grant was cancelled / the museum drastically reduced its opening hours / and postponed two exhibitions / rather than close the collection entirely.','drastically 修饰 reduced；rather than 引出没有采取的更极端选择。','大幅缩短开放时间且推迟展览，显示 drastic 程度的改变。'),'The museum drastically changed its schedule by moving opening time forward by one second.','The museum slightly changed its schedule by moving opening time forward by one second.','一秒钟的微调幅度很小，不适合用 drastically。',[q('drastically',1,1,'If a policy changes drastically, it changes?',['to a very great degree','in a tiny barely measurable way','only in its spelling'],'to a very great degree','drastically.s1 强调巨大、显著的变化。'),q('drastically',2,1,'Which cut is most likely described as drastic?',['a budget reduced by 60 percent','a budget reduced by one cent','a budget copied into another file unchanged'],'a budget reduced by 60 percent','削减六成属于大幅调整。'),q('drastically',3,1,'A drastic diet change should be?',['substantial and potentially demanding','a one-word spelling correction','an invisible change of punctuation'],'substantial and potentially demanding','drastic 描述程度很大、影响显著的改变。'),q('drastically',4,1,'The medicine drastically lowered the fever. What happened?',['the fever fell sharply','the fever rose imperceptibly','the patient changed the medicine’s label'],'the fever fell sharply','drastically 修饰 lowered，表示体温显著下降。')]);

put('draught','draught 是英式拼法的多义词，历史上与 draw（拉、牵引）相关；可指室内冷空气流，也可指文本的初稿。',c('draught.s1','居家维修','A cold draught came through the gap beneath the front door, so Mira rolled a towel along the threshold before the heating turned on.','冷风从前门下方的缝隙钻进来，因此暖气开启前，米拉先把毛巾卷放在门槛处。','A cold draught came through the gap beneath the front door / so Mira rolled a towel along the threshold / before the heating turned on.','draught 是 came 的主语；through 短语说明冷风进入的路径。','从门缝进入室内的冷空气是 draught.s1。'),'The cold draught was a first version of the essay that the author planned to revise.','The first draught of the essay was an early version that the author planned to revise.','表示文本初稿时 draught 不修饰 cold；冷风义与文本义不可混为一谈。',[q('draught',1,1,'A draught under a door is?',['a current of air entering the room','a polished final paragraph','a type of window glass'],'a current of air entering the room','draught.s1 是室内气流或穿堂风。'),q('draught',2,2,'The writer sent an early draught to a colleague. The writer sent?',['a preliminary version of the text','a cold breeze through a door','a finished building plan'],'a preliminary version of the text','draught.s2 可表示尚待修改的初稿。'),q('draught',3,1,'Which repair can stop a cold draught at a door?',['sealing the gap beneath it','opening a larger gap','removing the door entirely'],'sealing the gap beneath it','封住门下缝隙可阻挡冷风。'),q('draught',4,2,'“The report is only a draught” suggests it?',['may still be revised','is a current of cold air','has already been carved in stone'],'may still be revised','初稿尚未定稿，通常可以继续修改。')]);

put('dreadfully','dreadfully 是 dread 加副词后缀 -fully，可按语境表示令人恐惧地，也可在非正式英式用法中作程度副词“非常”。',c('dreadfully.s2','日常表达','The hotel room was dreadfully cold, so we asked the receptionist for an extra blanket before going to sleep.','酒店房间冷得厉害，所以我们睡前向接待员要了一条额外的毯子。','The hotel room was dreadfully cold / so we asked the receptionist for an extra blanket / before going to sleep.','dreadfully 修饰形容词 cold，作非正式程度副词；so 引出应对措施。','房间非常冷，体现 dreadfully.s2 的“非常”义。'),'They played the violin dreadfully, with perfect technique and a beautiful tone.','They played the violin beautifully, with perfect technique and a beautiful tone.','dreadfully 描述非常糟糕或令人不快的演奏，与称赞其技巧和音色相矛盾。',[q('dreadfully',1,1,'A dreadfully frightening sound is?',['one that causes strong fear','one that is pleasantly quiet','a measurement of room size'],'one that causes strong fear','dreadfully.s1 表示令人害怕地。'),q('dreadfully',2,2,'In informal British English, “dreadfully tired” can mean?',['extremely tired','slightly awake','afraid of a particular person'],'extremely tired','dreadfully.s2 可作程度副词“非常”。'),q('dreadfully',3,2,'Which sentence uses dreadfully as an intensifier?',['The soup was dreadfully hot, so we waited before eating.','The ghost dreadfully chased the children through the hall.','The report was dreadfully, with no adjective after it.'],'The soup was dreadfully hot, so we waited before eating.','dreadfully hot 中副词修饰形容词，表示“非常烫”。'),q('dreadfully',4,1,'A dreadfully cruel scene would make viewers feel?',['disturbed or afraid','well-rested','hungry for breakfast'],'disturbed or afraid','令人恐惧、痛苦的情景符合 dreadfully.s1。')]);

put('dreary','dreary 的远源词形解释并非透明复合构词；现代英语中它形容沉闷、阴郁、令人提不起精神的事物，不臆造词根。',c('dreary.s1','天气描写','A dreary drizzle lasted through the afternoon, and the empty streets looked even greyer beneath the low clouds.','沉闷的毛毛雨下了一下午，低云笼罩下空荡的街道显得更加灰暗。','A dreary drizzle lasted through the afternoon / and the empty streets looked even greyer / beneath the low clouds.','dreary 修饰 drizzle；even greyer 表示低云让街景更显阴沉。','持续小雨、低云和灰暗街道营造出沉闷阴郁的感觉。'),'The dreary afternoon was lively, sunny, and full of cheerful celebrations.','The dreary afternoon was dull, grey, and lacking in cheer.','热闹晴朗、充满欢庆与 dreary 的沉闷阴郁义相反。',[q('dreary',1,1,'A dreary day is typically?',['dull and cheerless','bright and exciting','brief and expensive'],'dull and cheerless','dreary.s1 指阴郁、沉闷、令人低落。'),q('dreary',2,1,'A dreary lecture may leave students feeling?',['bored and low in spirits','surprised by an exciting plot','physically taller'],'bored and low in spirits','沉闷乏味的讲座会使人感到无聊。'),q('dreary',3,1,'Which landscape is most likely called dreary?',['a grey, rainy plain with little colour','a brilliant garden during a festival','a sunny beach crowded with musicians'],'a grey, rainy plain with little colour','缺少色彩且阴沉的景象体现 dreary。'),q('dreary',4,1,'“The months of waiting were dreary” means the wait was?',['dull and dispiriting','full of suspenseful entertainment','over in a second'],'dull and dispiriting','dreary 形容漫长等待令人沉闷、提不起精神。')]);

put('dredge','dredge 作为动词与 dredge（疏浚设备）同形，指从水底挖除泥沙或捞取物体；相关机械名词也使用同一词形。',c('dredge.s2','港口维护','Each spring, the harbour authority dredges the channel to remove silt that accumulated over winter and to keep the route deep enough for cargo ships.','港务部门每年春季疏浚航道，清除冬季淤积的泥沙，使航路足够深，货船得以通行。','Each spring, the harbour authority dredges the channel / to remove silt that accumulated over winter / and to keep the route deep enough for cargo ships.','dredges 是及物动词；两个 to-infinitive 并列说明疏浚的目的。','清除航道底部淤泥以增加水深，符合 dredge.s2。'),'The harbour crew dredged the channel by adding more silt until it became shallower.','The harbour crew dredged the channel by removing silt until it became deeper.','疏浚是挖除水底泥沙以清理或加深航道，不是添加淤泥。',[q('dredge',1,1,'To dredge a harbour channel is to?',['remove mud or sand from its bottom','fill it with extra stones until blocked','paint its surface with warning signs'],'remove mud or sand from its bottom','dredge.s2 表示疏浚、清除水底沉积物。'),q('dredge',2,1,'Which machine might dredge a river?',['a boat fitted to scoop sediment from the bed','a bicycle designed for dry roads','a printing press for newspapers'],'a boat fitted to scoop sediment from the bed','dredge.s1 指挖泥机或挖泥船。'),q('dredge',3,2,'After a storm, workers dredged the canal to?',['clear deposited silt and restore depth','make the water shallower with extra mud','dry every fish on the bank'],'clear deposited silt and restore depth','挖除淤积物可恢复水深和通航能力。'),q('dredge',4,1,'A dredger raises sand from the seabed. The vessel is a?',['dredge','drake','drainpipe'],'dredge','用于从水底挖捞泥沙的船叫 dredge。')]);

put('driftwood','driftwood 是 drift 与 wood 构成的复合词，指被河流或海水带走、后来搁浅在岸上的木块。',c('driftwood.s1','海岸拾物','After the storm, pieces of driftwood lay above the tide line, bleached by salt and scattered among broken shells.','风暴过后，几块浮木散落在高潮线以上，被盐分漂白，与碎贝壳混在一起。','After the storm / pieces of driftwood lay above the tide line / bleached by salt / and scattered among broken shells.','driftwood 是不可数集合名词；pieces of 用来计数，bleached 与 scattered 描述木块状态。','被海水带来并搁浅的木块正是 driftwood。'),'The driftwood was freshly cut timber stacked inside a dry workshop before ever touching water.','The driftwood had been carried by water and washed onto the shore.','从未漂流、仍在工场里的新木材不是 driftwood。',[q('driftwood',1,1,'Driftwood is wood that has been?',['carried by water and left on a shore','cut and stored dry before reaching a river','turned into metal by heat'],'carried by water and left on a shore','driftwood.s1 指随水漂流后搁浅的木头。'),q('driftwood',2,1,'A beachcomber might collect driftwood after?',['a storm or high tide','a library closing','a snowfall in a desert'],'a storm or high tide','风暴和潮水会把浮木冲到海滩上。'),q('driftwood',3,1,'Which phrase is grammatically natural?',['pieces of driftwood','three driftwoods','a driftwood of water'],'pieces of driftwood','driftwood 通常作不可数名词，用 pieces of 计数。'),q('driftwood',4,1,'A sculpture made from driftwood uses?',['water-worn wood collected from a shore','newly sawn steel beams','fresh flowers from a greenhouse'],'water-worn wood collected from a shore','海岸收集的漂木可用作雕刻材料。')]);


put('drinking','drinking 由 drink 加 -ing 构成作名词，可泛指饮用液体，也常特指饮酒或饮酒行为。',c('drinking.s1','公共卫生','The campaign promotes regular water drinking during hot weather, while its separate guidance explains the health risks of heavy drinking.','这项宣传活动提倡炎热天气里定时喝水，另有单独指南说明大量饮酒的健康风险。','The campaign promotes regular water drinking during hot weather / while its separate guidance explains the health risks / of heavy drinking.','drinking 作名词；water drinking 指饮水，heavy drinking 在常见语境中特指大量饮酒。','并列语境区分普通饮水与常用的饮酒义。'),'The report uses “drinking” to mean eating solid bread and never refers to liquids or alcohol.','The report uses “drinking” for taking liquids; “heavy drinking” often refers to alcohol use.','drinking 的基本名词义与液体摄入有关，heavy drinking 常指饮酒。',[q('drinking',1,1,'In “drinking water,” drinking refers to?',['consuming liquid','chewing solid food','sleeping after exercise'],'consuming liquid','drinking.s1 的基本义是饮用液体。'),q('drinking',2,1,'A report warns that unsafe drinking water may cause illness. The concern is about?',['water people consume','the sound of a glass breaking','the colour of a cup'],'water people consume','drinking water 指供人饮用的水。'),q('drinking',3,1,'In the phrase “heavy drinking,” drinking most often means?',['consuming large amounts of alcohol','drinking one small glass of water','pouring paint into a bucket'],'consuming large amounts of alcohol','heavy drinking 常特指大量饮酒。'),q('drinking',4,1,'Which sentence uses drinking as a noun?',['Drinking enough water helps replace fluid lost in heat.','She drinks the glass carefully.','The drinker walked home.'],'Drinking enough water helps replace fluid lost in heat.','句首 Drinking 作动名词，表示饮用这一行为。')]);

put('dripstone','dripstone 是 drip 与 stone 的透明复合词，地质学中指矿物质丰富的水滴落、蒸发后沉积形成的洞穴矿物构造。',c('dripstone.s1','洞穴地质','A slender dripstone hung above the pool, where mineral-rich water kept depositing calcite as each drop evaporated.','一根细长的滴水石悬在水池上方，富含矿物质的水滴不断蒸发并沉积方解石。','A slender dripstone hung above the pool / where mineral-rich water kept depositing calcite / as each drop evaporated.','dripstone 是 hung 的主语；where 从句说明矿物沉积的洞穴环境和形成过程。','矿物质水滴蒸发后留下方解石沉积，符合 dripstone.s1。'),'The geologist identified the dripstone as a granite block formed instantly from dry cave dust.','The geologist identified the dripstone as a cave deposit formed as mineral-rich water dripped and evaporated.','dripstone 是洞穴中由含矿物质水沉积形成的构造，不是花岗岩块由干燥尘土瞬间形成。',[q('dripstone',1,1,'A dripstone in a cave forms as mineral-rich water?',['drips and leaves mineral deposits as it evaporates','freezes into a granite boulder instantly','flows upward as dry dust'],'drips and leaves mineral deposits as it evaporates','dripstone.s1 指水滴蒸发后形成的洞穴矿物沉积。'),q('dripstone',2,1,'Where would a geologist most likely find dripstone?',['inside a limestone cave','on a dry city pavement far from water','in a cloud above the ocean'],'inside a limestone cave','滴水石是洞穴中常见的矿物沉积构造。'),q('dripstone',3,1,'Which process supplies the minerals that build dripstone?',['mineral-rich water depositing material over time','wind blowing dry sand upward once','a metal tool carving granite'],'mineral-rich water depositing material over time','水中溶解的矿物逐渐沉积，构成滴水石。'),q('dripstone',4,1,'A stalactite hanging from a cave roof is an example of?',['dripstone','driftwood','a dune'],'dripstone','钟乳石是滴水石的一种形态。')]);
put('driveway','driveway 是 drive 与 way 组成的透明复合词，指从公共道路通往私人住宅或车库、供车辆通行的短路面。',c('driveway.s1','住宅出入','The delivery van remained on the driveway rather than blocking the pavement, while the driver carried the parcel to the front door.','送货车停在车道上，没有挡住人行道；司机把包裹送到了前门。','The delivery van remained on the driveway / rather than blocking the pavement / while the driver carried the parcel to the front door.','driveway 是介词 on 的宾语；rather than 对比车道与人行道。','连接街道、供车辆驶入住宅的私人道路是 driveway。'),'The family parked its car on the driveway, a path reserved exclusively for pedestrians inside the house.','The family parked its car on the driveway, the private approach from the street to the house.','driveway 是车辆驶入住宅的车道，不是室内人行小径。',[q('driveway',1,1,'A house driveway normally connects the home with?',['the street or road outside','an upstairs bedroom','a railway station platform'],'the street or road outside','driveway.s1 是从公共道路通往住宅的私人车道。'),q('driveway',2,1,'Where might a visitor leave a car at a suburban home?',['in the driveway','on the kitchen counter','inside the mailbox'],'in the driveway','住宅车道可供车辆停放或驶入。'),q('driveway',3,1,'A driveway is usually associated with?',['a private house or garage','a runway at an airport only','a riverbed under water'],'a private house or garage','driveway 通常位于住宅、车库附近。'),q('driveway',4,1,'Which sentence uses driveway naturally?',['Snow covered the driveway, so we cleared a path for the car.','The driveway cooked dinner for the guests.','She mailed a letter through the driveway.'],'Snow covered the driveway, so we cleared a path for the car.','车道积雪会影响汽车通行，搭配符合其含义。')]);

put('driving','driving 是 drive 加 -ing 构成的动名词或形容词；可指驾驶活动，也可修饰发挥主要推动作用的力量或因素。',c('driving.s2','组织管理','A driving force behind the clinic’s expansion was the need to serve villages that had no nearby medical centre.','推动诊所扩张的一项主要力量，是为附近没有医疗中心的村庄提供服务的需要。','A driving force behind the clinic’s expansion was the need to serve villages / that had no nearby medical centre.','driving 修饰 force，表示主要的推动因素；that 从句修饰 villages。','对扩张起主要推动作用的是服务缺医村庄的需要，符合 driving.s2。'),'A driving reason behind the project was a minor detail that had no influence on any decision.','A minor detail played little part in the project; a driving reason was the need for better access to care.','driving force/reason 指重要推动因素，不能指完全不起影响的细节。',[q('driving',1,1,'In “driving requires attention,” driving means?',['operating a vehicle','supplying a main motive','repairing a road surface'],'operating a vehicle','driving.s1 是驾驶车辆这一活动。'),q('driving',2,2,'A driving force behind reform is?',['a major factor that pushes the reform forward','a weak detail with no influence','a car used to deliver documents'],'a major factor that pushes the reform forward','driving.s2 表示主要推动力。'),q('driving',3,1,'Which action is part of safe driving?',['checking mirrors before changing lanes','closing one’s eyes at an intersection','reading a book while steering'],'checking mirrors before changing lanes','驾驶过程中观察镜子、确认路况是安全驾驶行为。'),q('driving',4,2,'In “ambition was her driving motivation,” driving suggests the motivation was?',['central and powerful','unrelated and unimportant','a vehicle’s steering wheel'],'central and powerful','driving 修饰 motivation，强调主要推动作用。')]);

put('dromedary','dromedary 经法语 dromadaire 进入英语，最终关联希腊语 dromas「善于奔跑的」；它特指阿拉伯单峰骆驼。',c('dromedary.s1','沙漠交通','A dromedary carried water containers and woven blankets across the desert, its single hump rising above the traveller’s saddle.','一峰骆驼驮着水罐和编织毯穿过沙漠，单峰高高隆起在旅人的鞍具上方。','A dromedary carried water containers and woven blankets across the desert / its single hump rising above the traveller’s saddle.','dromedary 是 carried 的主语；独立主格 its single hump rising 补充其外形。','明确提到单峰及沙漠运输，符合单峰骆驼义。'),'The dromedary crossed the sand on two humps, which is the defining feature of an Arabian camel.','The dromedary crossed the sand on its single hump, unlike a two-humped Bactrian camel.','单峰是 dromedary 的辨识特征；双峰对应双峰骆驼。',[q('dromedary',1,1,'A dromedary is a camel with?',['one hump','two humps','no legs'],'one hump','dromedary.s1 特指单峰骆驼。'),q('dromedary',2,1,'Which animal is most likely a dromedary?',['an Arabian camel with a single hump','a Bactrian camel with two humps','a horse adapted to the Arctic'],'an Arabian camel with a single hump','阿拉伯单峰骆驼就是 dromedary。'),q('dromedary',3,1,'A traveller crossing a hot desert chooses a dromedary mainly as?',['a pack or riding animal adapted to arid travel','a fish for carrying in a net','a snow sled pulled over ice'],'a pack or riding animal adapted to arid travel','单峰骆驼常用于干旱地区的骑乘和驮运。'),q('dromedary',4,1,'What feature separates a dromedary from a Bactrian camel?',['the number of humps','the presence of fur','the ability to drink water'],'the number of humps','单峰与双峰是两者最直观的区别。')]);

put('drop-off','drop-off 是 drop 加 off 构成的复合名词，可指数量或水平的明显下降，也可指送人或物后离开的地点。',c('drop-off.s1','客流统计','The museum saw a sharp drop-off in visitors after the bus route was suspended, especially among families who did not own cars.','公交线路停运后，博物馆访客数量明显下降，尤其是没有私家车的家庭。','The museum saw a sharp drop-off in visitors after the bus route was suspended / especially among families / who did not own cars.','drop-off 是 saw 的宾语；in visitors 指明下降的指标。','访客数量明显减少，体现 drop-off.s1。'),'The museum reported a drop-off in visitors because attendance doubled every week.','The museum reported a rise in visitors because attendance doubled every week.','人数每周翻倍表示增加，而非 drop-off 所指的下降。',[q('drop-off',1,1,'A drop-off in sales means sales have?',['fallen noticeably','doubled rapidly','stayed exactly constant'],'fallen noticeably','drop-off.s1 指数量或水平下降。'),q('drop-off',2,2,'A school’s drop-off point is where?',['parents leave children and then depart','teachers store exam papers permanently','students receive final grades'],'parents leave children and then depart','drop-off.s2 指送人下车、放下物品后离开的地点。'),q('drop-off',3,1,'Which report describes a drop-off in attendance?',['The audience shrank from 500 to 180.','The audience grew from 180 to 500.','The audience stayed at 500.'],'The audience shrank from 500 to 180.','观众人数减少就是 attendance 的 drop-off。'),q('drop-off',4,2,'A sign marked “passenger drop-off” indicates?',['a place where passengers may be left','a ticket office for buying train seats','a platform where trains are repaired'],'a place where passengers may be left','drop-off point 是让乘客下车的地点。')]);

put('drop-out','drop-out 是 drop out 的名词形式，指中途退出学校、大学或原定活动的人。',c('drop-out.s1','教育与培训','The adult learning centre paired each drop-out with a mentor who helped identify schedule conflicts and plan a realistic return to classes.','成人学习中心为每位辍学者配备导师，帮助其找出时间冲突，并制定切实可行的返校计划。','The adult learning centre paired each drop-out with a mentor / who helped identify schedule conflicts / and plan a realistic return to classes.','drop-out 作可数名词；who 引导定语从句修饰 mentor。','离开课程后得到返校支持，明确指曾退出学习的人。'),'The university called every graduate a drop-out, even though each had completed the entire degree.','The university called students who left before completing their degree drop-outs.','完成学位的人是毕业生；drop-out 指退出课程而未完成者。',[q('drop-out',1,1,'A school drop-out is someone who?',['leaves school before completing the course','finishes a degree successfully','teaches a course for many years'],'leaves school before completing the course','drop-out.s1 指中途离开学校或课程的人。'),q('drop-out',2,1,'A report on drop-outs would most likely examine?',['why learners leave before finishing','how many students earned diplomas','the colour of classroom walls'],'why learners leave before finishing','辍学研究关注中途退出的情况及其原因。'),q('drop-out',3,1,'Which person is a drop-out from a training programme?',['one who withdrew after two weeks','one who completed all modules','one who designed the final test'],'one who withdrew after two weeks','退出培训项目且未完成者符合定义。'),q('drop-out',4,1,'The phrase “college drop-out” identifies a person who?',['left college without completing the programme','was appointed college president','graduated with honours'],'left college without completing the programme','college drop-out 指中途离开大学的人。')]);

put('droplet','droplet 是 drop 加表示小物体的后缀 -let 构成，指一小滴水或其他液体。',c('droplet.s1','实验观察','A droplet formed on the chilled glass, slid slowly toward the table, and joined several smaller beads of condensation.','冰凉的玻璃杯上形成一滴水珠，慢慢滑向桌面，并与几颗更小的凝结水珠汇合。','A droplet formed on the chilled glass / slid slowly toward the table / and joined several smaller beads of condensation.','droplet 是并列谓语的主语；formed、slid、joined 按先后描述液滴变化。','玻璃表面形成的一小滴凝结水是 droplet.s1。'),'A droplet covered the entire lake and contained no liquid at all.','A droplet was a tiny bead of water on the glass.','droplet 是微小液滴，不能指覆盖整座湖的无液体实体。',[q('droplet',1,1,'A droplet is?',['a very small drop of liquid','a large dry stone','a cloudless stretch of sky'],'a very small drop of liquid','droplet.s1 是小液滴。'),q('droplet',2,1,'Which scene contains droplets?',['tiny beads of water on a cold bottle','dry sand stored in a jar','a metal plate with no moisture'],'tiny beads of water on a cold bottle','冷瓶表面的水珠是 droplets。'),q('droplet',3,1,'A scientist measures a droplet to study?',['a small amount of liquid','a mountain’s height','a bird’s wing span'],'a small amount of liquid','droplet 指少量液体形成的小滴。'),q('droplet',4,1,'In a mist, many droplets are?',['tiny suspended drops of water','large blocks of frozen rock','grains of dry flour'],'tiny suspended drops of water','雾由空气中悬浮的微小水滴组成。')]);

put('drowse','drowse 是表示昏昏欲睡或浅睡的动词；名词用法指困倦状态。其历史词源不宜仅凭拼写硬拆，现代词义与 drowsy 同属困倦词族。',c('drowse.s1','长途旅行','After lunch, Jonah began to drowse in the warm train carriage, but he woke whenever the conductor announced another station.','午饭后，乔纳在温暖的火车车厢里开始打瞌睡，不过列车员每次报站他都会醒来。','After lunch, Jonah began to drowse in the warm train carriage / but he woke / whenever the conductor announced another station.','begin to drowse 表示开始打瞌睡；whenever 引出每次醒来的触发情景。','仍会被报站声叫醒的浅睡状态符合 drowse.s1。'),'Jonah drowsed through the night in a deep, uninterrupted coma and could not be awakened.','Jonah slept deeply through the night without waking.','drowse 指浅睡或近乎入睡，不是无法唤醒的深昏迷。',[q('drowse',1,1,'To drowse is to?',['sleep lightly or begin to fall asleep','run at full speed','work with intense alertness'],'sleep lightly or begin to fall asleep','drowse.s1 指打瞌睡或浅睡。'),q('drowse',2,2,'A person sitting in a drowse is in a state of?',['light sleepiness','extreme physical strength','deep concentration on a puzzle'],'light sleepiness','drowse.s2 是困倦、浅睡状态。'),q('drowse',3,1,'Which passenger is beginning to drowse?',['one whose head nods while reading on a warm bus','one who is sprinting to catch a train','one who is fully alert and taking notes'],'one whose head nods while reading on a warm bus','点头、将睡未睡是 drowse 的典型状态。'),q('drowse',4,1,'A noise wakes a child who had started to drowse. The child had been?',['dozing lightly','running outdoors','speaking loudly'],'dozing lightly','浅睡容易被声音惊醒，符合 drowse。')]);

put('drowsiness','drowsiness 是 drowsy 加名词后缀 -ness，表示困倦、警觉性下降的感觉或状态。',c('drowsiness.s1','药品说明','The label warns that the antihistamine may cause drowsiness, so patients should avoid driving until they know how the medicine affects them.','药品标签提醒，这种抗组胺药可能引起困倦，因此患者应先了解药物对自己的影响，再决定是否开车。','The label warns that the antihistamine may cause drowsiness / so patients should avoid driving / until they know how the medicine affects them.','cause drowsiness 是“引起困倦”的搭配；until 从句限定何时可驾驶。','药物降低警觉、使人想睡，符合 drowsiness.s1。'),'The medicine caused drowsiness, leaving the driver more alert, energetic, and unable to feel tired.','The medicine caused drowsiness, leaving the driver sleepy and less alert.','困倦通常降低清醒程度，不会让驾驶者更加警觉。',[q('drowsiness',1,1,'Drowsiness is a feeling of being?',['sleepy and less alert','very hungry for salt','unable to hear any sound'],'sleepy and less alert','drowsiness.s1 指困倦、警觉性不足。'),q('drowsiness',2,1,'Why might a medicine label warn about drowsiness?',['the medicine may make users sleepy','the medicine guarantees better eyesight','the medicine removes the need for sleep'],'the medicine may make users sleepy','药物可能导致嗜睡，因此需提醒用户。'),q('drowsiness',3,1,'A driver experiencing drowsiness should?',['stop somewhere safe and rest','speed up to stay awake','ignore blurred attention and continue'],'stop somewhere safe and rest','困倦驾驶不安全，应先停车休息。'),q('drowsiness',4,1,'Which symptom most directly signals drowsiness?',['heavy eyelids and difficulty staying alert','a sudden increase in height','a stronger sense of smell'],'heavy eyelids and difficulty staying alert','眼皮沉重、难以保持清醒是困倦表现。')]);

put('drowsy','drowsy 在现代英语中表示困倦、想睡，也可形容使人昏昏欲睡的环境或药物；不把它强行切分成无据词根。',c('drowsy.s1','健康与休息','The drowsy passenger put away her phone, reclined her seat, and asked her friend to wake her before the airport stop.','昏昏欲睡的乘客收起手机、放低座椅，并请朋友在机场站前叫醒她。','The drowsy passenger put away her phone / reclined her seat / and asked her friend to wake her before the airport stop.','drowsy 修饰 passenger；ask + 人 + to do 表示请朋友叫醒她。','准备休息并担心睡过站表现出困倦。'),'The drowsy passenger was fully alert, wide awake, and struggling to stay asleep.','The sleepy passenger was struggling to stay awake.','drowsy 是想睡、困倦，与完全清醒且努力入睡相反。',[q('drowsy',1,1,'A drowsy person feels?',['ready to sleep','unable to stop laughing','eager to begin a sprint'],'ready to sleep','drowsy.s1 表示昏昏欲睡。'),q('drowsy',2,1,'A warm, quiet room may be described as drowsy if it?',['makes people feel sleepy','keeps everyone sharply alert','produces loud alarms'],'makes people feel sleepy','drowsy 也可形容使人困倦的气氛或环境。'),q('drowsy',3,1,'Which warning is sensible for a drowsy driver?',['Pull over safely before continuing.','Close your eyes at the next turn.','Drive faster through traffic.'],'Pull over safely before continuing.','困倦时驾驶会危及安全，应停车休息。'),q('drowsy',4,1,'Which phrase is a natural collocation?',['a drowsy afternoon','a drowsy equation of 2 plus 2','drowsy the door shut'],'a drowsy afternoon','drowsy 可形容令人困倦的午后。')]);

put('drub','drub 是旧有英语动词，词源细节不透明；现代用法表示反复殴打，也常比喻以悬殊比分彻底击败对手。',c('drub.s1','体育报道','The visiting team drubbed its rivals 6–0, scoring three times before halftime and controlling possession throughout the second half.','客队以六比零大胜对手，上半场就打入三球，并在下半场始终控制球权。','The visiting team drubbed its rivals 6–0 / scoring three times before halftime / and controlling possession throughout the second half.','drubbed 是及物动词，后接被击败的对手；比分说明胜利悬殊。','六比零的大比分胜利体现 drub.s1 的“彻底击败”义。'),'The visiting team drubbed its rivals 0–6, winning the match by six goals.','The visiting team was drubbed by its rivals 0–6, losing the match by six goals.','客队 0–6 落败；主动说它 drubbed 对手却称其获胜，颠倒了比分双方。',[q('drub',1,1,'To drub an opponent in a match is to?',['defeat the opponent by a large margin','draw with the opponent without scoring','invite the opponent to join a team'],'defeat the opponent by a large margin','drub.s1 常指在比赛中大胜对手。'),q('drub',2,1,'A team drubbed its rival 5–0. What was the result?',['a decisive victory','a scoreless tie','a narrow loss'],'a decisive victory','五比零是悬殊比分，表示彻底击败。'),q('drub',3,1,'In its literal sense, drub can mean to?',['beat someone repeatedly','praise someone quietly','lend someone a bicycle'],'beat someone repeatedly','drub 也有反复殴打的字面义。'),q('drub',4,1,'Which headline uses drub correctly?',['“Home Side Drubs Visitors in 7–1 Win”','“Home Side Drubbed Visitors in a 1–7 Defeat”','“Home Side Drubs the Rain into Sunshine”'],'“Home Side Drubs Visitors in 7–1 Win”','主队以七比一取胜，主动动词 drubs 用法正确。')]);

put('dryness','dryness 由 dry 加名词后缀 -ness 构成，可指缺乏水分，也可比喻文风或语气缺乏幽默、温暖和趣味。',c('dryness.s1','园艺管理','The dryness of the topsoil did not mean the roots were parched, so the gardener checked below the surface before watering the bed again.','表层土壤干燥并不代表根部缺水，因此园丁再次浇灌花圃前先检查了土层深处。','The dryness of the topsoil did not mean the roots were parched / so the gardener checked below the surface / before watering the bed again.','dryness 是 of 短语中心名词；did not mean 区分表层干燥与根部缺水。','土壤水分少的状态对应 dryness.s1。'),'The dryness of the soil meant it was saturated with water and dripping wet.','The dryness of the soil meant it contained little moisture.','干燥是缺少水分；饱和、滴水的土壤与其相反。',[q('dryness',1,1,'Soil dryness describes?',['a lack of moisture','an excess of liquid water','the soil’s temperature only'],'a lack of moisture','dryness.s1 指干燥、缺水分。'),q('dryness',2,2,'The dryness of a comedian’s style may mean it has?',['little humour or warmth','too much water','a very loud musical beat'],'little humour or warmth','dryness.s2 可比喻文风或语气缺少幽默感。'),q('dryness',3,1,'Cracked lips in winter may result from?',['dryness and low humidity','excessive rainfall on the lips','a change in shoe size'],'dryness and low humidity','低湿度会使皮肤、嘴唇缺水干燥。'),q('dryness',4,2,'A reviewer notes the dryness of a lecture. The reviewer likely means it was?',['dull and lacking liveliness','moist and easy to swim through','brief but very funny'],'dull and lacking liveliness','评论文风的 dryness 可指枯燥、缺少趣味。')]);

put('ductile','ductile 来自拉丁语 ductilis，关联 ducere「引导、牵引」；在材料学中指金属可拉成细丝而不断裂，也可旧式地指容易受引导。',c('ductile.s1','材料科学','Copper is ductile enough to be drawn into thin electrical wire, although the finished wire still needs insulation to prevent short circuits.','铜具有足够的延展性，可以拉成细电线，不过成品仍须包覆绝缘层以防短路。','Copper is ductile enough to be drawn into thin electrical wire / although the finished wire still needs insulation / to prevent short circuits.','ductile 修饰 Copper；be drawn into 表示拉制成，although 引出额外安全条件。','能被拉成细线而不断裂是 ductile.s1 的材料学定义。'),'The ductile metal snapped as soon as it was gently pulled into a thin wire.','The ductile metal could be pulled into a thin wire without snapping.','拉成细线时立即断裂说明材料缺乏延展性。',[q('ductile',1,1,'A ductile metal can be?',['drawn into wire without breaking','shattered by any gentle pull','turned into water at room temperature'],'drawn into wire without breaking','ductile.s1 指能拉成线而不断裂。'),q('ductile',2,1,'Which material property makes copper useful for wiring?',['ductility','brittleness','solubility in air'],'ductility','铜可拉成细线，体现延展性。'),q('ductile',3,2,'A ductile pupil in the older figurative sense is?',['easily guided or taught','physically made of copper','unable to change any opinion'],'easily guided or taught','ductile.s2 的比喻义是易受引导、易教导。'),q('ductile',4,1,'If a sample breaks while being drawn into a wire, it is?',['not sufficiently ductile','more ductile than copper','a liquid rather than a solid'],'not sufficiently ductile','延展性材料应能被拉长成丝而不折断。')]);

put('ductless','ductless 是 duct 加否定后缀 -less 构成，意为没有导管或不设管道；具体所指依生物、建筑或设备语境而定。',c('ductless.s1','医学影像','The radiologist described the lesion as a ductless gland, meaning it released its hormones directly into the bloodstream rather than through a tube.','放射科医生把该腺体描述为无导管腺，意思是它把激素直接释放到血液中，而不是经管道输送。','The radiologist described the lesion as a ductless gland / meaning it released its hormones directly into the bloodstream / rather than through a tube.','ductless 修饰 gland；meaning 引出对“无导管”的解释。','激素直接进入血液而不经导管，符合 ductless.s1。'),'A ductless gland sends every secretion through a long visible tube to the skin.','A ductless gland releases its secretion directly into surrounding tissue or blood rather than through a duct.','无导管腺的关键特征是不借助导管输送分泌物。',[q('ductless',1,1,'A ductless organ has?',['no duct or channel for carrying its secretion','an extra-long drainage pipe','two separate windpipes'],'no duct or channel for carrying its secretion','ductless.s1 表示没有导管。'),q('ductless',2,1,'Why are endocrine glands called ductless?',['they release hormones directly into the blood','they send hormones through ducts to the skin','they contain no cells'],'they release hormones directly into the blood','内分泌腺把激素释放入血，不经导管。'),q('ductless',3,1,'The suffix -less in ductless contributes the meaning?',['without','again','before'],'without','-less 表示“没有……的”。'),q('ductless',4,1,'Which description fits a ductless gland?',['its secretion enters nearby tissue or blood directly','its product must flow through a dedicated tube','it is a road used by cars'],'its secretion enters nearby tissue or blood directly','直接释放是无导管腺的特点。')]);

put('dues','dues 是 due 的复数形式，常指加入俱乐部、工会或组织须定期缴纳的会费，也可用于 pay one’s dues 的“尽应尽的义务、经受历练”。',c('dues.s1','会员管理','Members whose annual dues remain unpaid after the reminder receive a notice explaining the final payment date and how to renew online.','收到提醒后仍未缴年费的会员会收到通知，说明最后付款日期以及如何在线续费。','Members whose annual dues remain unpaid after the reminder / receive a notice / explaining the final payment date / and how to renew online.','dues 是 annual 的中心名词；whose 引导定语从句，说明尚未缴费的会员。','组织按年度收取的会费对应 dues.s1。'),'The club’s dues were a one-time cash prize paid to visitors with no membership.','The club’s dues were regular membership fees paid by its members.','dues 是会员应缴的费用，不是给非会员的一次性奖金。',[q('dues',1,1,'A club member pays annual dues to?',['maintain membership in the organization','buy a house from another member','receive a prize for leaving'],'maintain membership in the organization','dues.s1 指加入组织需定期缴纳的会费。'),q('dues',2,1,'“Membership dues are overdue” means the fees?',['should already have been paid','were unexpectedly refunded','belong to a different club'],'should already have been paid','overdue 表示缴费日期已过。'),q('dues',3,1,'In “pay one’s dues before promotion,” dues can figuratively mean?',['complete the work or hardships expected first','collect a prize without effort','avoid every responsibility'],'complete the work or hardships expected first','pay one’s dues 可比喻先尽责、经受历练。'),q('dues',4,1,'Which phrase most commonly refers to a union’s regular charges?',['union dues','union drapery','union droplet'],'union dues','工会会员缴纳的定期费用称 union dues。')]);

put('duet','duet 经意大利语 duetto 进入英语，最终来自 duo「二」；指由两位歌手或演奏者共同完成的音乐作品或表演。',c('duet.s1','音乐会','The violinist and cellist performed a duet written for two contrasting instruments, exchanging the melody while the piano supplied a quiet accompaniment.','小提琴手与大提琴手演奏了一首为两种音色迥异的乐器创作的二重奏，两人轮流演奏旋律，钢琴则轻声伴奏。','The violinist and cellist performed a duet / written for two contrasting instruments / exchanging the melody / while the piano supplied a quiet accompaniment.','duet 是 performed 的宾语；for two 表示二重奏由两位演奏者承担。','小提琴和大提琴两位演奏者共同表演，符合 duet.s1。'),'The singer performed a duet entirely alone, with no second voice or instrument.','The singer performed a solo entirely alone, with no second voice or instrument.','duet 需要两位演唱者或演奏者；独自表演应称 solo。',[q('duet',1,1,'A duet is music performed by?',['two singers or players','one singer only','an orchestra with no performers'],'two singers or players','duet.s1 指二重奏或二重唱。'),q('duet',2,1,'Two friends sing together on stage. Their performance is a?',['duet','solo','trio of three people'],'duet','两位歌手一起演唱形成二重唱。'),q('duet',3,1,'A piano-and-flute duet requires?',['two performers sharing the music','three separate orchestras','a silent audience only'],'two performers sharing the music','两件乐器由两位演奏者合作构成 duet。'),q('duet',4,1,'The root idea in duet is connected with the number?',['two','seven','one hundred'],'two','duet 关联意大利语 duetto 和 duo，含“两”之意。')]);

put('dugout','dugout 由 dug 与 out 构成，原指挖出的土坑或掩体，也可指挖空整根木头制成的独木舟；棒球中另指球员席。',c('dugout.s2','棒球比赛','When the pitcher was replaced, his teammates met him at the dugout steps, offered a towel, and discussed the next defensive lineup.','投手被换下后，队友在球员席台阶处迎接他，递上毛巾，并讨论接下来的防守阵容。','When the pitcher was replaced / his teammates met him at the dugout steps / offered a towel / and discussed the next defensive lineup.','dugout 是介词 at 的宾语；棒球情景中的队友、投手和阵容锁定球员席义。','球员在场边下沉式席位休息与交流，符合 dugout.s2。'),'The pitcher rested in the dugout, a canoe carved from a tree and launched across the ocean.','The pitcher rested in the dugout, the sunken bench beside the baseball field.','棒球语境里的 dugout 是球队坐席，不是独木舟。',[q('dugout',1,1,'A team’s baseball dugout is?',['the sunken bench area where players sit','a tunnel beneath home plate to the sea','a wooden bat storage room only'],'the sunken bench area where players sit','dugout.s2 是棒球场边的球员席。'),q('dugout',2,1,'An archaeological dugout shelter is made by?',['digging a pit or hollow into the ground','building a tall glass tower','weaving cloth on a loom'],'digging a pit or hollow into the ground','dugout.s1 可指挖出的土坑或掩体。'),q('dugout',3,1,'A dugout canoe is formed by?',['hollowing out a log','joining two metal aeroplanes','folding a paper map'],'hollowing out a log','独木舟是挖空整根木头制作的。'),q('dugout',4,2,'The coach shouted instructions from the dugout during the inning. Where was the coach?',['in the team area beside the field','at the centre of a river in a canoe','inside an underground bomb shelter'],'in the team area beside the field','教练在比赛中的 dugout 即球队席。')]);

put('duke','duke 经古法语 duc 源自拉丁语 dux「领袖」，历史上与 ducere「引领」相关；它指英国贵族序列中的最高世袭等级之一。',c('duke.s1','贵族制度','The duke opened the estate’s archive to local researchers, although the title itself passed to his eldest child under the family’s hereditary rules.','公爵向当地研究者开放了庄园档案，不过按照家族世袭规则，头衔本身由其长子女继承。','The duke opened the estate’s archive to local researchers / although the title itself passed to his eldest child / under the family’s hereditary rules.','duke 是 opened 的主语；although 从句区分个人行动与头衔继承。','世袭贵族头衔的持有者是 duke.s1。'),'The duke was an elected municipal clerk with no noble title or hereditary rank.','The duke held a hereditary noble title, though elected clerks may administer the same town.','duke 指贵族头衔持有者，不是普通民选行政职员。',[q('duke',1,1,'In the British peerage, a duke holds?',['the highest hereditary noble rank','a temporary elected school office','a military rank below every private'],'the highest hereditary noble rank','duke.s1 是英国贵族序列中最高等级的世袭头衔。'),q('duke',2,1,'A duchess is most closely associated with a?',['duke','dun(e)','duet'],'duke','duchess 是 duke 对应的女性头衔或配偶称号。'),q('duke',3,1,'A family archive says the duke inherited his title. This means the title was?',['passed through hereditary succession','won in a singing contest','a job elected every month'],'passed through hereditary succession','公爵头衔通常按世袭规则继承。'),q('duke',4,1,'Which use of duke is accurate?',['The duke attended the royal ceremony as a nobleman.','The duke is a small drop of water.','She played a duke on the violin.'],'The duke attended the royal ceremony as a nobleman.','duke 指贵族身份或头衔持有者。')]);

put('dulcimer','dulcimer 作为传统乐器名，经中古英语而来，常追溯至中古拉丁语 dulce melos「甜美的乐声」；现代常指以小槌敲弦的梯形扬琴，亦指阿巴拉契亚拨弦琴。',c('dulcimer.s1','民间音乐','The player struck the hammered dulcimer’s courses with two light mallets, producing a bright, ringing melody above the guitar accompaniment.','演奏者用两把轻槌敲击扬琴的弦组，在吉他伴奏上方奏出明亮清脆的旋律。','The player struck the hammered dulcimer’s courses with two light mallets / producing a bright, ringing melody / above the guitar accompaniment.','dulcimer 是 struck 的宾语；with 引出敲弦工具，hammered dulcimer 锁定击弦乐器。','用小槌击打梯形琴弦的乐器是扬琴类 dulcimer。'),'The hammered dulcimer is a brass wind instrument played by blowing through a mouthpiece.','The hammered dulcimer is a string instrument whose strings are struck with small hammers.','hammered dulcimer 是击弦乐器，不是靠吹奏发声的铜管乐器。',[q('dulcimer',1,1,'A hammered dulcimer produces sound when a player?',['strikes its strings with light hammers','blows air through a brass mouthpiece','rubs a bow across a drum'],'strikes its strings with light hammers','dulcimer.s1 的一种常见乐器以小槌击弦。'),q('dulcimer',2,1,'A dulcimer belongs to which broad instrument family?',['string instruments','wind instruments only','electronic keyboards only'],'string instruments','扬琴和阿巴拉契亚 dulcimer 都属于弦乐器。'),q('dulcimer',3,1,'Which description fits an Appalachian dulcimer?',['a fretted string instrument played by plucking or strumming','a hammered brass bell','a reed pipe with no strings'],'a fretted string instrument played by plucking or strumming','Appalachian dulcimer 是有品格的拨弦乐器。'),q('dulcimer',4,1,'The older name’s “dulce melos” is commonly interpreted as?',['sweet melody','heavy wooden cart','winter mountain'],'sweet melody','dulcimer 的历史名称常与拉丁语“甜美的乐声”联系。')]);

put('duly','duly 是 due 加副词后缀 -ly，表示依照要求或适当方式完成，也可说某事如期或按预期发生。',c('duly.s1','行政手续','The committee duly recorded the objections in its minutes and sent each speaker a copy of the final decision the following week.','委员会按规定把反对意见记录在会议纪要中，并于次周向每位发言者寄送最终决定。','The committee duly recorded the objections in its minutes / and sent each speaker a copy / of the final decision / the following week.','duly 修饰 recorded，表示依程序适当记录；following week 交代发送时间。','会议记录按程序完成，体现 duly.s1 的适当、如期之义。'),'The committee duly ignored its own procedure and never recorded the required objections.','The committee duly recorded the required objections according to its procedure.','完全无视程序且未记录材料，不是按规定恰当地完成。',[q('duly',1,1,'If a form is duly signed, it has been signed?',['properly as required','accidentally by a stranger','only in invisible ink'],'properly as required','duly.s1 表示适当地、依照要求地。'),q('duly',2,1,'“The parcel duly arrived on Friday” suggests that it?',['arrived as expected or at the proper time','was lost forever','arrived before it was sent'],'arrived as expected or at the proper time','duly 也可表示如期、按预期发生。'),q('duly',3,1,'Which action was duly completed?',['the required report was filed in the correct office','the report was thrown away unsigned','the deadline was ignored without explanation'],'the required report was filed in the correct office','依要求提交到正确部门，属于 duly completed。'),q('duly',4,1,'In “the winner was duly announced,” duly indicates the announcement was?',['made as expected or officially','secretly cancelled','a measure of distance'],'made as expected or officially','duly announced 表示按程序或预期正式宣布。')]);

put('dumbfound','dumbfound 由 dumb 与 confound 组合形成，字面上带有“使惊得说不出话”的意味，现代动词表示使人极为惊讶。',c('dumbfound.s1','意外发现','The archaeologists were dumbfounded when the sealed chamber contained a complete wooden boat, preserved beneath the temple for more than two thousand years.','考古学家发现密封房间里竟有一艘完整木船，在神庙下保存了两千多年，不禁惊呆了。','The archaeologists were dumbfounded / when the sealed chamber contained a complete wooden boat / preserved beneath the temple / for more than two thousand years.','be dumbfounded 表示感到震惊；when 从句交代令人惊讶的发现。','出乎意料且极不寻常的发现使考古学家惊讶得说不出话。'),'The unexpected discovery dumbfounded the researchers, leaving everyone completely unsurprised and calmly repeating what they already knew.','The unexpected discovery dumbfounded the researchers, leaving them astonished and momentarily speechless.','dumbfound 表示使人非常惊讶；称所有人完全不惊讶，和句首的 dumbfounded 直接矛盾。',[q('dumbfound',1,1,'To dumbfound someone is to?',['astonish the person greatly','give the person a quiet instruction','make the person fall asleep gently'],'astonish the person greatly','dumbfound.s1 指使人极为惊讶。'),q('dumbfound',2,1,'A scientist was dumbfounded by an impossible-looking result. The scientist was?',['astonished and momentarily speechless','bored by a familiar chart','angry about a missing chair'],'astonished and momentarily speechless','dumbfound 含惊讶到说不出话的意味。'),q('dumbfound',3,1,'Which discovery might dumbfound a team?',['an ancient room containing an intact ship','a folder containing the expected daily report','a door opening after someone turns its handle'],'an ancient room containing an intact ship','异常且出乎意料的发现最可能使人惊呆。'),q('dumbfound',4,1,'Choose the natural sentence.',['The child was dumbfounded by the sudden appearance of a magician.','The child dumbfounded to sleep at nine.','The dumbfound was blue and square.'],'The child was dumbfounded by the sudden appearance of a magician.','be dumbfounded by 描述人被意外之事惊到。')]);

put('dunce','dunce 源于人名 John Duns Scotus；其追随者曾被对手蔑称为 dunces，后来词义泛化为被认为愚笨或学习迟缓的人，属于贬义称呼。',c('dunce.s1','教育用语史','The teacher rejected the old “dunce” label, explaining that a student who struggles with fractions may simply need a different explanation and more practice.','老师拒绝使用旧式的“笨学生”标签，并解释说，分数学习吃力的学生可能只需要换一种讲解方式并多加练习。','The teacher rejected the old “dunce” label / explaining that a student who struggles with fractions / may simply need a different explanation and more practice.','dunce 是 label 的补语名词；who 从句修饰 student，语境指出其贬损色彩。','把学习者贬称为笨蛋的旧标签对应 dunce.s1，同时语境提醒这是侮辱性用语。'),'The teacher praised the child as a dunce because the word is a respectful title for a brilliant scholar.','The teacher avoided calling the child a dunce because the word is an insulting label for a supposedly stupid person.','dunce 是贬义称呼，不是尊敬聪明学者的头衔。',[q('dunce',1,1,'A dunce is an insulting name for someone thought to be?',['stupid or unable to learn','exceptionally wealthy','skilled at sailing'],'stupid or unable to learn','dunce.s1 是对被认为愚笨者的贬称。'),q('dunce',2,1,'Why should a teacher avoid calling a learner a dunce?',['it is a hurtful label and ignores how people learn','it is the formal name for a degree','it means a person who teaches fractions'],'it is a hurtful label and ignores how people learn','dunce 带有侮辱意味，易伤害学习者。'),q('dunce',3,1,'The word dunce has a historical connection to?',['the name John Duns Scotus','the name of a famous desert','a type of musical duet'],'the name John Duns Scotus','词源来自哲学家 John Duns Scotus 的姓名。'),q('dunce',4,1,'Which description handles dunce responsibly?',['It is a pejorative term, so use it cautiously when discussing historical usage.','It is a neutral official term for all pupils.','It is a polite synonym for professor.'],'It is a pejorative term, so use it cautiously when discussing historical usage.','该词具有贬义，应说明其冒犯性并谨慎使用。')]);

put('dune','dune 经法语 dune、荷兰语 duin 进入英语，最终关联日耳曼语中“沙丘/沙地”的词形；它指风塑造、推动的沙堆。',c('dune.s1','海岸地貌','Native grasses anchored the dune above the beach, reducing erosion while allowing wind to reshape the upper slope over time.','本地草固定了海滩上方的沙丘，减轻侵蚀，同时仍让风逐渐塑造其上坡。','Native grasses anchored the dune above the beach / reducing erosion / while allowing wind to reshape the upper slope over time.','dune 是 anchored 的宾语；while 对比固沙植物与持续风塑作用。','海滩上被风塑造并由植物固定的沙堆就是 dune.s1。'),'The dune was a deep ocean trench filled with water and far below the seabed.','The dune was a mound of sand shaped by wind near the coast.','dune 是沙丘而非海底水沟。',[q('dune',1,1,'A dune is a mound made chiefly of?',['sand','freshwater ice','solid iron'],'sand','dune.s1 指沙丘。'),q('dune',2,1,'What commonly shapes a dune?',['wind moving sand over time','a factory printing paper','a river flowing uphill'],'wind moving sand over time','风会搬运沙粒并塑造沙丘。'),q('dune',3,1,'Where might a coastal dune form?',['along a sandy beach above the high-water line','inside a deep city subway tunnel','at the centre of a paved airport runway'],'along a sandy beach above the high-water line','海滩上方常有风成沙丘。'),q('dune',4,1,'Plants on a dune can help?',['hold sand in place and reduce erosion','turn the sand into seawater','stop every breeze permanently'],'hold sand in place and reduce erosion','草根能固定沙丘表层，减轻侵蚀。')]);

put('dung','dung 是古英语传下来的普通名词，指动物的固体排泄物，常用作农田肥料；作为动词时指把粪肥撒到土地上。',c('dung.s1','农业施肥','The farmer spread well-rotted dung over the vegetable plot in autumn, then mixed it into the soil before planting spring crops.','农夫秋天把充分腐熟的粪肥撒在菜地上，随后在种植春季作物前将其翻入土壤。','The farmer spread well-rotted dung over the vegetable plot / then mixed it into the soil / before planting spring crops.','dung 作不可数名词，作 spread 的宾语；well-rotted 修饰腐熟后的肥料。','动物粪便经腐熟后施入土壤作肥料，体现 dung.s1。'),'The farmer called a bottle of synthetic blue dye dung and spread it on the vegetable plot as manure.','The farmer spread animal dung over the plot as manure to enrich the soil.','dung 指动物粪便，不是合成染料。',[q('dung',1,1,'Farmers may use dung as?',['animal manure for soil','a sterile glass window','a synthetic blue paint'],'animal manure for soil','dung.s1 指动物粪便，也常作肥料。'),q('dung',2,2,'To dung a field means to?',['spread manure over it','remove every plant from it','paint its fence blue'],'spread manure over it','动词 dung.s2 表示给土地施粪肥。'),q('dung',3,1,'Which source produces dung?',['livestock such as cattle','a keyboard printer','a rain gauge'],'livestock such as cattle','家畜排出的固体粪便是 dung。'),q('dung',4,1,'Before applying dung to a vegetable plot, a farmer may let it?',['rot or compost so it is suitable as manure','turn into clean drinking water','freeze into glass'],'rot or compost so it is suitable as manure','腐熟粪肥可用作土壤改良材料。')]);

put('dungeon','dungeon 经古法语 donjon 进入英语；该词早期可指城堡主塔，后来常指城堡或地下用于关押囚犯的阴暗牢房。',c('dungeon.s1','城堡历史','The guide described the dungeon below the keep, where narrow windows admitted little light and prisoners once waited behind a heavy iron door.','导游介绍了主堡下方的地牢，那里的窄窗几乎透不进光，囚犯曾被关在沉重的铁门后。','The guide described the dungeon below the keep / where narrow windows admitted little light / and prisoners once waited behind a heavy iron door.','dungeon 是 described 的宾语；where 从句补充地牢的位置和环境。','主堡下方阴暗、用来囚禁犯人的牢房是 dungeon.s1。'),'The castle dungeon was a bright open-air garden where prisoners freely held public concerts.','The castle dungeon was a dark enclosed cell where prisoners were kept.','开放明亮且任意出入的花园与地牢关押犯人的功能相反。',[q('dungeon',1,1,'A dungeon in a castle was typically?',['a dark cell used to hold prisoners','a bright public dining hall','a tower for growing crops'],'a dark cell used to hold prisoners','dungeon.s1 指阴暗的地牢或牢房。'),q('dungeon',2,1,'A novel’s prisoner was locked below ground behind a heavy door. The room was a?',['dungeon','driveway','duet'],'dungeon','地下关押犯人的牢房可称 dungeon。'),q('dungeon',3,1,'Which detail best fits a dungeon?',['little light and secure confinement','open windows, fresh air, and free exit','a sandy mound moved by wind'],'little light and secure confinement','阴暗、封闭、关押犯人是典型地牢特征。'),q('dungeon',4,1,'The older French source donjon first referred to a castle’s?',['main tower or keep','private garden gate','kitchen utensil'],'main tower or keep','dungeon 的法语词源早期曾指城堡主塔。')]);

put('duplication','duplication 由 duplicate 加名词后缀 -ion 构成，指制作完全相同的副本，也可指重复做同一项工作。',c('duplication.s1','档案管理','The archive prevents duplication by checking each incoming photograph against its catalogue before adding a new record.','档案馆在新增记录前先把每张新照片与目录核对，以免重复收录。','The archive prevents duplication / by checking each incoming photograph against its catalogue / before adding a new record.','duplication 是 prevents 的宾语；by 引出避免重复的具体方式。','避免将同一照片再次录入，就是防止复制品或重复记录。'),'The archive prevented duplication by entering the same photograph twice under identical details.','The archive prevented duplication by checking for an existing identical photograph before entry.','同一照片用相同信息录入两次会产生重复，不能防止 duplication。',[q('duplication',1,1,'Duplication of a file creates?',['an additional copy of the same file','a completely unrelated original','a shorter folder name'],'an additional copy of the same file','duplication.s1 指制作相同副本。'),q('duplication',2,1,'A manager avoids duplication of work by?',['checking whether a colleague already completed the task','assigning the same task twice without coordination','deleting every project record'],'checking whether a colleague already completed the task','duplication 也指重复做同一工作。'),q('duplication',3,1,'A duplicate entry in a database is?',['a repeated record of the same item','a record of a new unrelated item','an empty screen with no data'],'a repeated record of the same item','重复记录属于 duplication。'),q('duplication',4,1,'Which action is an example of duplication?',['printing a second identical copy of a report','writing a new report on a different subject','reading one report once'],'printing a second identical copy of a report','制作完全相同的第二份报告就是复制。')]);

put('dusky','dusky 由 dusk 加形容词后缀 -y 构成，可指暮色般微暗，也可形容偏暗、低沉的色调。',c('dusky.s1','黄昏景色','A dusky light settled over the harbour as the sun disappeared, and the fishing boats became dark shapes against the last strip of orange sky.','太阳落下时，港口笼罩在微暗的暮色中，渔船成了橙色天际最后一线余晖前的黑影。','A dusky light settled over the harbour / as the sun disappeared / and the fishing boats became dark shapes / against the last strip of orange sky.','dusky 修饰 light；as 引导黄昏时刻，dark shapes 呼应光线微暗。','日落后光线转暗但尚未全黑，体现 dusky.s1。'),'The dusky sky at noon was brilliantly bright, cloudless, and lit as strongly as midday sun.','The dusky sky at twilight was dim and shadowy as daylight faded.','正午强光与微暗、暮色般的 dusky 形成鲜明反义。',[q('dusky',1,1,'A dusky evening is?',['somewhat dark as daylight fades','brilliantly bright at noon','completely colourless because it is underground'],'somewhat dark as daylight fades','dusky.s1 指暮色般微暗。'),q('dusky',2,1,'A painter chooses a dusky blue for a room. The colour is likely?',['darkish and muted','glowing neon yellow','pure white'],'darkish and muted','dusky 可指较暗、低沉的颜色。'),q('dusky',3,1,'When would a dusky glow most likely appear?',['around twilight after sunset','at the brightest moment of noon','inside a sealed unlit box'],'around twilight after sunset','黄昏光线变暗，常呈 dusky。'),q('dusky',4,1,'Which image best fits dusky?',['dim hills fading into evening shadow','a sunlit white wall at noon','a flash of brilliant lightning'],'dim hills fading into evening shadow','暮色中的暗影山丘符合 dusky 的阴暗义。')]);

put('dusty','dusty 由 dust 加形容词后缀 -y 构成，指表面覆有细小干燥尘土，也可形容因久置而显得陈旧的物品。',c('dusty.s1','图书馆整理','A dusty atlas lay unopened on the top shelf, and a thin grey layer fell away when the librarian lifted it for the history class.','一本布满灰尘的地图册一直没在顶层书架上打开过；管理员为历史课取下时，薄薄的灰层掉了下来。','A dusty atlas lay unopened on the top shelf / and a thin grey layer fell away / when the librarian lifted it for the history class.','dusty 修饰 atlas；灰层脱落为“表面有尘”提供语境证据。','书本表面覆盖一层灰尘，符合 dusty.s1。'),'The dusty table had just been washed and was completely free of dust or dirt.','The dusty table had a visible layer of fine dry dirt on its surface.','刚洗净且毫无灰尘的桌面与 dusty 的字面义相反。',[q('dusty',1,1,'A dusty shelf is covered with?',['a layer of fine dry dirt','fresh liquid paint','smooth clear ice'],'a layer of fine dry dirt','dusty.s1 表示布满灰尘。'),q('dusty',2,1,'Why might an unused book be dusty?',['fine particles have settled on it over time','it is submerged in clean water','it has been polished every hour'],'fine particles have settled on it over time','长期放置会让灰尘落在物品表面。'),q('dusty',3,1,'Which task would clean a dusty desk?',['wiping off the accumulated dust','adding more dry dirt','covering it with flour'],'wiping off the accumulated dust','擦拭可除去表面灰尘。'),q('dusty',4,1,'A “dusty old tradition” is figuratively?',['outdated and little used','new and rapidly changing','made from wet clay'],'outdated and little used','比喻 dusty 可形容陈旧、少有人用的事物。')]);

put('dweller','dweller 由 dwell 加施事者后缀 -er 构成，指长期居住或栖息在某处的人或动物，常见于 city-dweller、cave-dweller 等复合词。',c('dweller.s1','城市生活','As a lifelong city-dweller, Noor knew which side streets stayed quiet at rush hour and where residents could find a public garden.','作为长期生活在城市里的人，努尔知道哪些支路在高峰期仍很安静，也知道居民可以在哪里找到公共花园。','As a lifelong city-dweller / Noor knew which side streets stayed quiet at rush hour / and where residents could find a public garden.','city-dweller 是介词 as 的补语，说明 Noor 的居住背景；连字符将 city 与 dweller 构成复合词。','city-dweller 是居住在城市里的人。'),'A city-dweller is a traveller who visits a city once and never lives there.','A city-dweller is someone who lives in a city.','偶尔到访者不是居住者，dweller 指在某处生活的人。',[q('dweller',1,1,'A city-dweller is someone who?',['lives in a city','only flies over a city','designed a city map once'],'lives in a city','dweller.s1 指居住或栖息于某处的人。'),q('dweller',2,1,'A cave-dweller would make a home in?',['a cave','a courthouse','a ship’s mast'],'a cave','复合词 cave-dweller 指住在洞穴里的人。'),q('dweller',3,1,'Which animal could be described as a forest-dweller?',['a species that lives in the forest','a visitor passing through once','a cloud above the forest'],'a species that lives in the forest','dweller 也可用于长期栖居某地的动物。'),q('dweller',4,1,'The suffix -er in dweller identifies?',['a person or thing that does or is associated with the base action','the past tense of dwell','a measurement of distance'],'a person or thing that does or is associated with the base action','-er 在 dweller 中构成表示居住者的名词。')]);

put('dwindle','dwindle 的早期词源与古英语 dwīnan「衰退、消失」相关，后来的词形发展并非透明规则派生；现代义是逐渐缩小或减少。',c('dwindle.s1','水资源监测','During the prolonged drought, the reservoir dwindled month by month, exposing stones that had remained underwater for decades.','长期干旱期间，水库水位逐月下降，露出了几十年来一直沉在水下的石块。','During the prolonged drought / the reservoir dwindled month by month / exposing stones / that had remained underwater for decades.','dwindled 作不及物动词；month by month 强调逐渐变化，exposing 表结果。','水位一点点下降并露出石头，体现逐渐减少的过程。'),'The reservoir dwindled overnight by filling with more water until it reached its highest level.','The reservoir dwindled during the drought as its water level gradually fell.','持续减少与因补水升至最高水位相反。',[q('dwindle',1,1,'If a supply dwindles, it?',['gradually becomes smaller','suddenly doubles','stays perfectly unchanged'],'gradually becomes smaller','dwindle.s1 强调逐渐减少或缩小。'),q('dwindle',2,1,'A crowd dwindled after the rain began. What happened?',['fewer people remained over time','the crowd instantly became twice as large','everyone arrived at the same moment'],'fewer people remained over time','人数逐渐变少就是 dwindling。'),q('dwindle',3,1,'Which sentence uses dwindle accurately?',['Our savings dwindled as monthly costs continued.','Our savings dwindled when a large deposit doubled them.','Our savings dwindled while remaining exactly constant.'],'Our savings dwindled as monthly costs continued.','支出持续消耗积蓄，符合逐渐减少。'),q('dwindle',4,1,'The verb dwindle usually describes a change that is?',['gradual rather than instantaneous','a deliberate loud announcement','a change in spelling only'],'gradual rather than instantaneous','dwindle 表示逐渐缩减，常伴有时间过程。')]);

put('dyestuff','dyestuff 是 dye 与 stuff 的复合名词，指能赋予材料持久颜色的天然或合成物质。',c('dyestuff.s1','纺织工艺','The textile maker tested the dyestuff on a spare strip of wool, checking whether sunlight would fade the colour before treating the whole batch.','纺织工匠先在一条备用羊毛上测试染料，确认日晒是否会使颜色褪去后才处理整批布料。','The textile maker tested the dyestuff on a spare strip of wool / checking whether sunlight would fade the colour / before treating the whole batch.','dyestuff 是 tested 的宾语；checking 分词说明测试内容。','用于给羊毛赋予颜色并检验牢度的物质是 dyestuff。'),'The dyestuff removed all colour from the wool and was used only as a cleaning solvent.','The dyestuff added a lasting colour to the wool and was tested for resistance to fading.','dyestuff 是染色材料，不是专门褪色的清洁溶剂。',[q('dyestuff',1,1,'A dyestuff is a material used to?',['give another material colour','remove every colour from a surface','measure the weight of wool'],'give another material colour','dyestuff.s1 指染料物质。'),q('dyestuff',2,1,'A textile maker would apply dyestuff to?',['fabric or fibre to colour it','a ruler to measure length','a window to stop rain'],'fabric or fibre to colour it','染料可用于给布料或纤维着色。'),q('dyestuff',3,1,'Why test dyestuff in sunlight?',['to see whether its colour fades','to check whether it makes wool heavier','to determine the fabric’s age'],'to see whether its colour fades','日晒测试可检验染料的颜色牢度。'),q('dyestuff',4,1,'Which is a plausible source of dyestuff?',['a natural plant pigment or synthetic colourant','a dry stone with no pigment','a piece of uncoloured glass'],'a natural plant pigment or synthetic colourant','天然颜料和合成着色剂都可作染料。')]);

put('dynamical','dynamical 由 dynamics 加形容词后缀 -al 构成，指与力如何产生运动或变化有关的；在科学语境常与 dynamic 同义。',c('dynamical.s1','物理建模','The dynamical model tracked how gravitational forces altered the moon’s orbit over time rather than treating its position as fixed.','这个动力学模型追踪了引力如何随时间改变月球轨道，而不是把它的位置视为固定不变。','The dynamical model tracked how gravitational forces altered the moon’s orbit over time / rather than treating its position as fixed.','dynamical 修饰 model；how 从句说明模型研究力与运动的关系。','模型探讨引力导致的轨道变化，属于动力学研究。'),'A dynamical model assumes that forces never cause motion or change and records only a fixed portrait.','A static portrait records a fixed position; a dynamical model examines how forces produce motion or change.','动力学研究力与变化，完全静止的描绘并非该领域的核心。',[q('dynamical',1,1,'A dynamical analysis focuses on?',['how forces produce motion or change','the spelling of place names','the colour of a motionless page'],'how forces produce motion or change','dynamical.s1 指动力学的，研究力和运动变化。'),q('dynamical',2,1,'A dynamical model of a planet might track?',['how gravity changes its orbit','the planet’s name printed on a poster','a photograph with no motion data'],'how gravity changes its orbit','引力对轨道的影响是动力学问题。'),q('dynamical',3,1,'In a physics paper, dynamical is closely related to?',['dynamics','drapery','drowsiness'],'dynamics','dynamical 是 dynamics 的形容词形式。'),q('dynamical',4,1,'Which question is dynamical?',['How does the force alter the object’s motion?','What is the object’s label colour?','How many letters are in its name?'],'How does the force alter the object’s motion?','它询问力如何导致运动变化，符合动力学。')]);

put('dynamism','dynamism 由 dynamic 加名词后缀 -ism 构成，表示充沛活力、推动力，或愿意不断适应和改变的特质。',c('dynamism.s1','企业文化','The start-up’s dynamism came from engineers who tested ideas quickly, learned from failed prototypes, and revised the product each month.','这家初创公司的活力来自一群工程师：他们快速测试想法，从失败的原型中吸取经验，并每月改进产品。','The start-up’s dynamism came from engineers / who tested ideas quickly / learned from failed prototypes / and revised the product each month.','dynamism 是 came from 的主语；who 引导的并列动作具体说明活力的来源。','快速尝试、学习和持续调整体现组织的活力与适应能力。'),'The organisation’s dynamism came from refusing every new idea and keeping all methods unchanged.','The organisation’s dynamism came from energetic teams willing to test ideas and adapt.','拒绝变化、保持停滞与 dynamism 所指的活力和开放变化相矛盾。',[q('dynamism',1,1,'Dynamism is a quality of being?',['energetic and ready to act or change','inactive and resistant to every idea','made entirely of metal'],'energetic and ready to act or change','dynamism.s1 指活力、干劲及变化能力。'),q('dynamism',2,1,'A company praised for dynamism probably?',['adapts quickly and pursues new opportunities','avoids all decisions indefinitely','does not communicate with customers'],'adapts quickly and pursues new opportunities','快速适应、主动探索显示组织有活力。'),q('dynamism',3,1,'Which example shows dynamism in a community?',['residents organise new services as needs change','residents reject every repair and proposal','an empty building remains unused'],'residents organise new services as needs change','因应新需要采取行动体现社区活力。'),q('dynamism',4,1,'In an economic report, dynamism suggests?',['vigorous activity and capacity for development','a complete absence of movement','the weight of a single machine'],'vigorous activity and capacity for development','经济活力包含积极活动和发展能力。')]);

put('dyspepsia','dyspepsia 来自希腊语 dys-「不良」与 pepsis「消化」，医学上指进食后上腹部疼痛或不适，常译消化不良。',c('dyspepsia.s1','医疗咨询','The patient reported recurring upper-abdominal discomfort after meals, and the clinician recorded dyspepsia while asking about medicines and other symptoms.','患者报告饭后反复出现上腹不适，临床医生在询问药物和其他症状的同时记录了消化不良。','The patient reported recurring upper-abdominal discomfort after meals / and the clinician recorded dyspepsia / while asking about medicines and other symptoms.','dyspepsia 是 recorded 的宾语；after meals 与上腹不适是该医学词义的典型语境。','饭后上腹部不适对应 dyspepsia.s1；例句不把词义当作具体病因诊断。'),'The note used dyspepsia to describe a broken ankle caused by a fall, with no digestive symptoms.','The note used dyspepsia for the patient’s upper-abdominal discomfort after eating.','dyspepsia 指消化不良相关的上腹不适，不是踝关节外伤。',[q('dyspepsia',1,1,'Dyspepsia refers to discomfort mainly associated with?',['digestion and the upper abdomen','an ankle joint after a fall','a hearing test'],'digestion and the upper abdomen','dyspepsia.s1 是消化不良、饭后上腹不适。'),q('dyspepsia',2,1,'A person reporting dyspepsia may describe?',['upper-abdominal discomfort after eating','a broken finger with no stomach symptoms','sudden loss of hearing'],'upper-abdominal discomfort after eating','该词通常描述饭后消化系统不适。'),q('dyspepsia',3,1,'Which word parts suggest the basic idea of dyspepsia?',['dys- “bad” plus a Greek root for digestion','dys- “two” plus “foot”','a Latin word for sunlight'],'dys- “bad” plus a Greek root for digestion','词源由表示不良的 dys- 和与消化有关的 pepsis 构成。'),q('dyspepsia',4,1,'In a clinical note, dyspepsia names?',['a symptom pattern, not by itself a specific cause','a broken ankle','a type of hearing aid'],'a symptom pattern, not by itself a specific cause','消化不良描述症状；具体原因需另外评估。')]);

put('dystrophy','dystrophy 由希腊语 dys-「不良」与 trophē「营养、发育」构成，指因营养利用异常或遗传疾病导致的组织消耗、萎缩等状况。',c('dystrophy.s1','医学科普','The specialist explained that the inherited muscle dystrophy gradually weakens muscle tissue and that monitoring can help the family plan supportive care.','专科医生解释说，这种遗传性肌营养不良会逐渐削弱肌肉组织，而定期监测有助于家庭规划支持性照护。','The specialist explained that the inherited muscle dystrophy gradually weakens muscle tissue / and that monitoring can help the family / plan supportive care.','dystrophy 是弱化肌肉组织的主语；that 从句说明疾病进展及管理。','遗传性肌肉组织逐渐受损属于 dystrophy.s1 的医学义。'),'The clinician used dystrophy to mean that healthy tissue had become stronger and larger through normal exercise.','The clinician used dystrophy for abnormal wasting or degeneration of tissue.','dystrophy 指异常的组织损耗或退化，不是健康组织正常增强。',[q('dystrophy',1,1,'Dystrophy broadly involves?',['abnormal wasting or degeneration of tissue','normal growth of a healthy plant','a temporary change in hair colour'],'abnormal wasting or degeneration of tissue','dystrophy.s1 指组织营养不良、萎缩或退化。'),q('dystrophy',2,1,'Muscular dystrophy primarily affects?',['muscle tissue','a person’s library card','the colour of seawater'],'muscle tissue','肌营养不良影响肌肉组织。'),q('dystrophy',3,1,'The Greek element trophē contributes the idea of?',['nourishment or development','a musical duet','a legal title'],'nourishment or development','trophē 与营养、发育相关。'),q('dystrophy',4,1,'A health article uses “dystrophy” to describe tissue that?',['is abnormally weakened or wasted','has grown stronger through ordinary training','is simply covered with dust'],'is abnormally weakened or wasted','组织异常削弱、萎缩符合 dystrophy 的词义。')]);

put('e-mail','e-mail 是 electronic mail 的缩略复合词，既可作名词指电子邮件或电子邮件系统，也可作动词表示通过邮件发送消息。',c('e-mail.s1','办公通信','Please send the signed form by e-mail before noon, and keep the original document in the office file for the audit.','请在中午前通过电子邮件发送签署后的表格，并把原件留在办公室档案中备查。','Please send the signed form by e-mail before noon / and keep the original document / in the office file for the audit.','by e-mail 是发送方式；邮件副本与纸质原件在语境中作区分。','电子方式传送的数字消息是 e-mail.s1。'),'The office sent the signed form by e-mail as a sealed paper envelope delivered by bicycle.','The office sent the signed form by e-mail as a digital message attached to the address.','e-mail 是数字通信方式，不是骑车投递的纸质信封。',[q('e-mail',1,1,'An e-mail is a message sent?',['digitally through an electronic mail system','only as a handwritten letter','through a pipe under a road'],'digitally through an electronic mail system','e-mail.s1 指电子邮件或其通信媒介。'),q('e-mail',2,2,'To e-mail a colleague means to?',['send the colleague a message electronically','meet the colleague for lunch','print the colleague’s photograph'],'send the colleague a message electronically','e-mail.s2 可作动词表示发邮件。'),q('e-mail',3,1,'A file attached to an e-mail is?',['a digital document sent with the message','a paper envelope attached to a mailbox','a public road to a house'],'a digital document sent with the message','邮件附件是随电子消息传送的数字文件。'),q('e-mail',4,1,'Which sentence uses e-mail as a noun?',['I received an e-mail with the meeting agenda.','I e-mail the report yesterday.','She is e-mailing her manager now.'],'I received an e-mail with the meeting agenda.','received 的宾语 e-mail 是名词。')]);

put('eagerly','eagerly 由 eager 加副词后缀 -ly 构成，表示带着热切期待、积极兴趣或急于行动的状态。',c('eagerly.s1','学习活动','The children eagerly raised their hands when the teacher announced a visit to the science centre, each hoping to ask the first question.','老师宣布要参观科学中心时，孩子们热切地举起手，都希望第一个提问。','The children eagerly raised their hands / when the teacher announced a visit to the science centre / each hoping to ask the first question.','eagerly 修饰 raised，说明举手的热情；when 从句提供诱因。','主动抢着提问表现出兴趣和期待，符合 eagerly.s1。'),'The children eagerly refused to attend the trip and showed no interest in the science centre.','The children eagerly agreed to attend the trip because they were excited about the science centre.','热切地参与和明确拒绝、毫无兴趣相矛盾。',[q('eagerly',1,1,'To wait eagerly for news is to wait?',['with keen interest and anticipation','without caring whether news arrives','while trying to fall asleep'],'with keen interest and anticipation','eagerly.s1 表示热切期待。'),q('eagerly',2,1,'A volunteer eagerly accepts a task. The volunteer is?',['enthusiastic and willing to begin','angry and unwilling to help','physically asleep'],'enthusiastic and willing to begin','eagerly 描述积极愿意、希望尽快行动。'),q('eagerly',3,1,'Which sentence uses eagerly naturally?',['She eagerly opened the letter from the university.','She eagerly was a blue letter.','The eagerliest door opened.'],'She eagerly opened the letter from the university.','副词 eagerly 修饰 opened，表达急切期待。'),q('eagerly',4,1,'The crowd eagerly awaited the result. What did the crowd feel?',['strong anticipation','complete indifference','sleepiness caused by medicine'],'strong anticipation','await eagerly 表示热切盼望结果。')]);

put('earner','earner 由 earn 加施事者后缀 -er 构成，指通过工作或其他来源获得收入的人，常见复合词有 wage-earner 和 high-earner。',c('earner.s1','家庭收入','The survey counts each wage-earner separately, because two adults in one household may both receive income from paid work.','这项调查分别统计每位工薪收入者，因为同一家庭中的两名成年人都可能有有偿工作的收入。','The survey counts each wage-earner separately / because two adults in one household / may both receive income from paid work.','wage-earner 是 counts 的宾语；because 从句解释为何按人分别统计。','从有偿工作获得工资的人是 wage-earner。'),'The report called a person with no wages or other income a high earner solely because the person owned an empty wallet.','The report called someone who receives a high salary a high earner.','没有收入的人不能因空钱包而称为 high earner。',[q('earner',1,1,'A wage-earner is a person who?',['receives wages from work','prints a weekly calendar','owns a train station'],'receives wages from work','earner.s1 指获得工资或收入的人。'),q('earner',2,1,'A high-earner usually receives?',['a comparatively high income','no income at all','only parcels by mail'],'a comparatively high income','high-earner 表示收入较高的人。'),q('earner',3,1,'Which phrase refers to someone who earns a living?',['an income earner','a window drapery','a coastal dune'],'an income earner','income earner 是指获得收入的人。'),q('earner',4,1,'The suffix -er in earner signals?',['a person who earns','the act of earning in the past','a place where mail arrives'],'a person who earns','-er 把 earn 派生为表示人的名词。')]);

put('earnestness','earnestness 由 earnest 加名词后缀 -ness 构成，表示认真、真挚、专注于目标的态度。',c('earnestness.s1','公开讨论','Her earnestness was clear when she listened without interruption, cited the evidence carefully, and acknowledged the limits of her proposal.','她认真诚恳的态度显而易见：她耐心倾听、谨慎引用证据，也承认自己提案的局限。','Her earnestness was clear / when she listened without interruption / cited the evidence carefully / and acknowledged the limits of her proposal.','earnestness 是 was 的主语补语；三个并列动作展现认真诚恳的表现。','认真倾听、据证论述并承认局限表现出 earnestness。'),'His earnestness showed in mocking every speaker and refusing to discuss the proposal seriously.','His earnestness showed in listening respectfully and discussing the proposal seriously.','嘲笑发言者、拒绝认真讨论说明缺乏诚意和认真。',[q('earnestness',1,1,'Earnestness is the quality of being?',['serious, sincere, and intent','careless and mocking','quiet only because one is asleep'],'serious, sincere, and intent','earnestness.s1 指认真、诚挚的态度。'),q('earnestness',2,1,'A student’s earnestness is shown by?',['careful preparation and sincere effort','copying answers while laughing at the task','leaving every question blank for fun'],'careful preparation and sincere effort','认真准备并真诚投入显示 earnestness。'),q('earnestness',3,1,'An earnest apology is likely?',['sincere rather than joking','made only to mock the listener','an unrelated weather report'],'sincere rather than joking','earnest 表示真挚、不是开玩笑。'),q('earnestness',4,1,'Which contrast best captures earnestness?',['sincere commitment versus casual indifference','wet cloth versus dry cloth','a duet versus a solo'],'sincere commitment versus casual indifference','earnestness 强调真诚投入，与冷漠相对。')]);

put('earthen','earthen 由 earth 加形容词后缀 -en 构成，指由泥土或烧制黏土制成；常见搭配有 earthen pot、earthenware。',c('earthen.s1','传统器皿','The cook simmered beans in an earthen pot over low heat, then carried the heavy vessel to the table with both hands.','厨师用陶土锅以小火炖豆子，随后双手把沉重的锅端到桌上。','The cook simmered beans in an earthen pot over low heat / then carried the heavy vessel to the table / with both hands.','earthen 修饰 pot，说明器皿由陶土制成；over low heat 描述烹饪方式。','以烧制黏土制成的锅是 earthen.s1。'),'The earthen pot was made from transparent glass that could bend like rubber.','The earthen pot was made from fired clay and could crack if dropped.','earthen 指土或烧制黏土材质，不是透明玻璃或橡胶。',[q('earthen',1,1,'An earthen pot is made mainly from?',['earth or fired clay','clear glass fibres','woven cotton thread'],'earth or fired clay','earthen.s1 表示泥制或陶土制成的。'),q('earthen',2,1,'Which object is most likely earthen?',['a clay jar fired in a kiln','a steel bicycle frame','a paper envelope'],'a clay jar fired in a kiln','烧制陶土罐是 earthen 器皿。'),q('earthen',3,1,'An earthen wall might be built from?',['packed soil or clay','transparent liquid water','thin sheets of metal only'],'packed soil or clay','earthen 也可修饰由土筑成的墙。'),q('earthen',4,1,'The suffix -en in earthen contributes the sense?',['made of or relating to earth','without earth','again and again'],'made of or relating to earth','-en 在 earthen 中形成“由土制成的”形容词。')]);

put('earthward','earthward 由 earth 与表示方向的 -ward 构成，意为朝向地球或地面，常用于下落、运动方向的描述。',c('earthward.s1','天体观测','After the satellite released the capsule, its heat shield turned earthward and the craft began a controlled descent through the atmosphere.','卫星释放返回舱后，隔热罩转向地球，飞行器开始受控穿过大气层下降。','After the satellite released the capsule / its heat shield turned earthward / and the craft began a controlled descent through the atmosphere.','earthward 作方向副词性补语，表示朝向地球；descent 补充其运动路径。','返回舱转向地球并下降，符合 earthward.s1。'),'The capsule turned earthward and travelled away from the planet into deep space.','The capsule turned earthward and descended toward the planet.','earthward 表示朝地球方向；远离地球飞入深空方向相反。',[q('earthward',1,1,'A spacecraft moving earthward is moving?',['toward Earth','away from Earth into deep space','parallel to a page'],'toward Earth','earthward.s1 指朝向地球或地面。'),q('earthward',2,1,'A falling meteor travels earthward as it?',['approaches the planet’s surface','leaves the solar system','moves horizontally inside a book'],'approaches the planet’s surface','陨石朝地球运动即 earthward。'),q('earthward',3,1,'Which phrase uses earthward correctly?',['the capsule began an earthward descent','the capsule climbed earthward away from Earth','an earthward recipe for soup'],'the capsule began an earthward descent','朝地球下降是 earthward 的自然搭配。'),q('earthward',4,1,'The directional element -ward means?',['in the direction of','without any','in the manner of a person'],'in the direction of','-ward 表示朝某方向移动或指向。')]);

put('earthwork','earthwork 是 earth 与 work 构成的复合词，可指挖土、填土等土方工程，也可指由土堆筑的防御工事。',c('earthwork.s1','遗址勘察','The survey mapped an earthwork along the ridge, where an ancient rampart of packed soil still outlined the edge of the settlement.','测绘人员绘出了山脊上的土垒遗址；古代夯土防御墙仍勾勒着聚落边缘。','The survey mapped an earthwork along the ridge / where an ancient rampart of packed soil / still outlined the edge of the settlement.','earthwork 是 mapped 的宾语；where 从句解释土垒的形态和位置。','夯土筑成的防御墙属于 earthwork.s1 的土垒义。'),'The ancient earthwork was a glass tower built without any soil or excavation.','The ancient earthwork was a defensive bank built by moving and packing soil.','土垒由搬运、堆筑土石形成，不是玻璃塔。',[q('earthwork',1,1,'An earthwork built for defence may be?',['a bank or rampart made from earth','a glass office tower','a musical performance for two'],'a bank or rampart made from earth','earthwork.s1 可指夯土建成的土垒、防御工事。'),q('earthwork',2,1,'On a construction site, earthwork can include?',['excavating soil and building an embankment','composing a song for violin','painting an indoor canvas'],'excavating soil and building an embankment','工程义 earthwork 指挖、运、填土等作业。'),q('earthwork',3,1,'Which feature is most likely an ancient earthwork?',['a raised soil rampart around a settlement','a steel bridge above a river','a carved wooden easel'],'a raised soil rampart around a settlement','聚落周围的夯土防御墙属于土工遗迹。'),q('earthwork',4,1,'A report on earthwork measures?',['how much ground is excavated or moved','how much rain falls on a roof','how many notes a duet contains'],'how much ground is excavated or moved','土方工程关注挖运土量和地形改造。')]);

put('earthworm','earthworm 是 earth 与 worm 组成的复合词，指在土中掘穴、身体分节柔软的环节动物。',c('earthworm.s1','土壤生态','After rain, an earthworm surfaced beside the garden bed; its burrows help loosen the soil and allow air and water to move through it.','雨后，一条蚯蚓从花圃旁钻出地面；它的洞穴有助于疏松土壤，让空气和水在其中流动。','After rain, an earthworm surfaced beside the garden bed / its burrows help loosen the soil / and allow air and water to move through it.','earthworm 是 surfaced 的主语；分号后解释蚯蚓洞穴的生态作用。','在土中钻穴并疏松土壤的动物是 earthworm.s1。'),'The earthworm flew above the garden on feathered wings and never entered soil.','The earthworm burrowed through the garden soil and helped aerate it.','蚯蚓无翅，在土中掘穴；飞行与其形态、习性相反。',[q('earthworm',1,1,'An earthworm is a?',['soft, segmented animal that burrows in soil','bird with feathers that nests in trees','hard mineral found in a quarry'],'soft, segmented animal that burrows in soil','earthworm.s1 指生活在土中的分节蠕虫。'),q('earthworm',2,1,'Why can earthworms benefit a garden?',['their burrows loosen and aerate the soil','they seal every pore in the soil','they turn the soil into plastic'],'their burrows loosen and aerate the soil','蚯蚓活动可使土壤疏松通气。'),q('earthworm',3,1,'Where is an earthworm most likely found?',['in moist soil after rain','on a high tree branch building a nest','inside a dry metal toolbox'],'in moist soil after rain','蚯蚓常在湿润土壤中活动，雨后可能爬出地表。'),q('earthworm',4,1,'The word earthworm combines earth with a word for?',['a worm-like animal','a flowering plant','a type of boat'],'a worm-like animal','earthworm 是“earth + worm”的复合名词。')]);

put('easel','easel 经荷兰语 ezel「驴」进入英语；因支架像驮物的架子而得名，现代指支撑画布或画板的画架。',c('easel.s1','绘画课程','The student set her canvas on an easel, adjusted the legs to face the north window, and began sketching the still life.','学生把画布架在画架上，调整支腿使其朝向北窗，然后开始画静物。','The student set her canvas on an easel / adjusted the legs to face the north window / and began sketching the still life.','easel 是 set 的介词宾语；on an easel 表示画布由画架支撑。','承托画布、便于站立绘画的支架是 easel.s1。'),'The painter placed the canvas on an easel, a drinking vessel used to hold water.','The painter placed the canvas on an easel, a stand that supports a canvas while it is painted.','easel 是画布支架，不是饮水容器。',[q('easel',1,1,'An artist uses an easel to?',['support a canvas while working','mix paint with water','store finished letters'],'support a canvas while working','easel.s1 指支撑画布的画架。'),q('easel',2,1,'Which item is normally placed on an easel?',['a canvas or drawing board','a bicycle wheel','a dinner plate for serving food'],'a canvas or drawing board','画布或画板可架在画架上。'),q('easel',3,1,'A portable easel is useful because it?',['holds the painting upright for the artist','carries water through a roof','plays music with two singers'],'holds the painting upright for the artist','画架让作品保持直立，便于作画。'),q('easel',4,1,'The word easel is historically linked to a Dutch word meaning?',['donkey','ocean','window'],'donkey','easel 经荷兰语 ezel「驴」进入英语。')]);

put('easily','easily 由 easy 加副词后缀 -ly 构成，表示毫不费力地、轻易地；也可表示很可能或毫无疑问。',c('easily.s1','教学评估','Because the instructions used familiar examples and short steps, most pupils could easily assemble the small weather station without help.','由于说明采用熟悉的例子和简短步骤，大多数学生都能轻松地独立组装小型气象站。','Because the instructions used familiar examples and short steps / most pupils could easily assemble the small weather station / without help.','easily 修饰 assemble，说明组装所需努力很少；because 从句交代原因。','熟悉例子和分步说明降低难度，体现 easily.s1。'),'The pupils assembled the model easily, struggling for hours with every simple step.','The pupils assembled the model easily, completing each simple step with little effort.','花数小时苦苦挣扎与 easily“毫不费力地”矛盾。',[q('easily',1,1,'If a task is done easily, it is done?',['with little effort or difficulty','only after many years of struggle','in an expensive location'],'with little effort or difficulty','easily.s1 指容易地、几乎不费力地。'),q('easily',2,1,'A good map helps hikers find the trail easily. It helps them find it?',['without much trouble','only by guessing in the dark','after crossing an unrelated ocean'],'without much trouble','easily 修饰 find，强调寻找过程简单。'),q('easily',3,1,'Which sentence uses easily naturally?',['She could easily lift the empty box.','She easily was a blue box.','The easily arrived before Monday.'],'She could easily lift the empty box.','副词 easily 修饰 lift，表示动作不费力。'),q('easily',4,1,'“That was easily the best option” can mean it was?',['clearly or unquestionably the best','the most difficult to identify','a physical object that weighs little'],'clearly or unquestionably the best','easily 也可加强最高级，表示显然、毫无疑问。')]);

put('eccentricity','eccentricity 由 eccentric 加名词后缀 -ity 构成；可指个人独特怪癖，也可指轨道或曲线偏离圆形的程度。',c('eccentricity.s2','天文学','The planet’s orbital eccentricity is low, so its path remains nearly circular even though its distance from the star changes slightly during the year.','这颗行星的轨道离心率较低，因此即使它与恒星的距离一年中略有变化，轨道仍近乎圆形。','The planet’s orbital eccentricity is low / so its path remains nearly circular / even though its distance from the star changes slightly during the year.','eccentricity 是 is 的主语中心词；low eccentricity 对应接近圆形轨道。','轨道偏离圆形的度量很低，体现 eccentricity.s2。'),'The orbit’s eccentricity was zero, meaning it was maximally stretched into a straight line.','The orbit’s eccentricity was high, meaning it was strongly elongated rather than circular.','离心率为零对应圆形轨道；极度拉长的轨道则离心率较高。',[q('eccentricity',1,1,'A person’s eccentricity refers to?',['unusual behaviour characteristic of that person','the speed of a train','the amount of water in a glass'],'unusual behaviour characteristic of that person','eccentricity.s1 指某人的古怪行为或怪癖。'),q('eccentricity',2,2,'In orbital mechanics, eccentricity measures?',['how far an orbit differs from a circle','how bright a star appears','how many planets orbit a star'],'how far an orbit differs from a circle','eccentricity.s2 衡量轨道偏离圆形的程度。'),q('eccentricity',3,2,'A perfectly circular orbit has eccentricity?',['zero','one thousand','a value measured in kilograms'],'zero','圆轨道离心率为零。'),q('eccentricity',4,1,'Collecting spoons shaped like local buildings may be described as someone’s?',['eccentricity','ecliptic','ecotourism'],'eccentricity','个人独特、不寻常的习惯可称 eccentricity。')]);

put('echinoderm','echinoderm 由希腊语 echinos「刺猬、带刺物」与 derma「皮肤」组成，指海星、海胆、海参等棘皮动物。',c('echinoderm.s1','海洋生物','The diver photographed an echinoderm on the reef: five arms radiated from the sea star’s centre, and tube feet clung to the rock.','潜水员拍下礁石上的一只棘皮动物：海星的五条腕从中心辐射开来，管足紧贴岩石。','The diver photographed an echinoderm on the reef / five arms radiated from the sea star’s centre / and tube feet clung to the rock.','echinoderm 是 photographed 的宾语；冒号后的细节以海星为例说明该动物类群。','海星属于棘皮动物，符合 echinoderm.s1。'),'The biologist classified the sea star as an echinoderm, a feathered mammal with fur and wings.','The biologist classified the sea star as an echinoderm, a marine invertebrate in the group that also includes sea urchins.','海星是海洋无脊椎动物，不是有毛、有翅的哺乳动物。',[q('echinoderm',1,1,'Which animal is an echinoderm?',['a sea star','a sparrow','a house cat'],'a sea star','echinoderm.s1 包括海星、海胆等海洋动物。'),q('echinoderm',2,1,'Sea urchins and sea cucumbers belong to the same broad group of?',['echinoderms','birds','flowering trees'],'echinoderms','海胆、海参都属于棘皮动物门。'),q('echinoderm',3,1,'The word parts echino- and -derm refer to?',['spiny and skin','winged and feather','water and sound'],'spiny and skin','词源中 echinos 与 derma 分别关联刺与皮肤。'),q('echinoderm',4,1,'An echinoderm is generally a?',['marine invertebrate','land bird','freshwater tree'],'marine invertebrate','棘皮动物是生活在海洋中的无脊椎动物。')]);

put('echoic','echoic 由 echo 加形容词后缀 -ic 构成，指模仿自然声音形成的；常见于描述拟声词或声音表达。',c('echoic.s1','语言学习','The children recognised “buzz” as an echoic word because its sound imitates the low, continuous noise made by a bee.','孩子们认出 buzz 是拟声词，因为这个词的声音模仿了蜜蜂发出的低沉、连续嗡鸣。','The children recognised “buzz” as an echoic word / because its sound imitates the low, continuous noise / made by a bee.','echoic 修饰 word；because 从句解释词音与实际声音间的模仿关系。','词形模仿蜂鸣声，正体现 echoic.s1 的拟声义。'),'“Buzz” is an echoic word because its sound has no relation to any sound in nature.','“Buzz” is an echoic word because its sound imitates a buzzing noise.','拟声词 echoic 的关键恰是词语声音模仿自然声。',[q('echoic',1,1,'An echoic word is formed to?',['imitate a sound','name a royal rank','describe a mathematical orbit'],'imitate a sound','echoic.s1 指拟声的、模仿声音的。'),q('echoic',2,1,'Which word is echoic because it resembles a noise?',['hiss','economist','easel'],'hiss','hiss 的发音模仿漏气声或蛇的嘶声。'),q('echoic',3,1,'“Click” can be called echoic because?',['its sound resembles a short clicking noise','it contains the letters of “climate”','it describes a person’s income'],'its sound resembles a short clicking noise','词的声音模拟轻微的咔哒声。'),q('echoic',4,1,'An echoic expression relies mainly on a link between?',['the sound of a word and a sound it imitates','a word’s spelling and a royal title','a sentence’s length and its price'],'the sound of a word and a sound it imitates','拟声表达通过语音模仿外界声音。')]);

put('echolocation','echolocation 是 echo 与 location 的复合词，指动物或装置发出声音并分析回声，以判断物体位置、方向或距离。',c('echolocation.s1','动物导航','Bats navigate through a dark cave using echolocation, sending out high-frequency calls and interpreting the returning echoes from nearby walls and insects.','蝙蝠利用回声定位穿过黑暗洞穴：它们发出高频叫声，再分析附近墙壁和昆虫反射回来的回声。','Bats navigate through a dark cave using echolocation / sending out high-frequency calls / and interpreting the returning echoes / from nearby walls and insects.','using echolocation 表示导航方式；分词短语解释发声和接收回声的步骤。','发出声波并分析回声来判断位置正是 echolocation.s1。'),'The bat used echolocation by ignoring every returning sound and navigating only by sunlight in the cave.','The bat used echolocation by sending calls and interpreting their echoes in the cave.','回声定位依赖发声及回声分析，不是忽略回声或依赖洞穴阳光。',[q('echolocation',1,1,'Echolocation works by an animal?',['sending out sound and interpreting returning echoes','using colour alone to measure temperature','reading a map printed on its wings'],'sending out sound and interpreting returning echoes','echolocation.s1 指发声并利用回声定位。'),q('echolocation',2,1,'Which animal commonly uses echolocation to navigate?',['a bat','a sunflower','a mountain pine'],'a bat','蝙蝠能用回声定位判断周围物体。'),q('echolocation',3,1,'A returning echo can help an animal estimate?',['an object’s direction or distance','the object’s legal owner','the age of the sun'],'an object’s direction or distance','回声信息可用于估计物体位置与距离。'),q('echolocation',4,1,'A dolphin clicks and listens for reflected sound to find fish. This is?',['echolocation','eclecticism','earthwork'],'echolocation','海豚也可用点击声及回声定位猎物。')]);

put('eclat','eclat 来自法语 éclat，原与“爆裂、闪耀”相关，英语中指耀眼的成功、显著的赞誉或出众的风采。',c('eclat.s1','艺术评论','The young pianist made her debut with éclat, earning a standing ovation for a performance that combined precision with unusual warmth.','这位年轻钢琴家以辉煌表现完成首演，凭借兼具精准与独特温情的演奏赢得全场起立鼓掌。','The young pianist made her debut with éclat / earning a standing ovation / for a performance that combined precision with unusual warmth.','with éclat 是方式短语，表示首演卓有成效、广受赞誉；earning 分词说明结果。','首演引发起立鼓掌，符合 eclat.s1 的显著成功、盛誉义。'),'The concert ended without notice, acclaim, or success, yet the review praised its eclat.','The concert ended to conspicuous acclaim, and the review praised its éclat.','毫无关注或赞誉与 eclat 所指的耀眼成就、盛誉不相符。',[q('eclat',1,1,'A performance received eclat when it earned?',['conspicuous praise and success','complete silence and no notice','a fine for parking'],'conspicuous praise and success','eclat.s1 指显著的赞誉或辉煌成功。'),q('eclat',2,1,'The phrase “with éclat” means?',['with brilliance or striking success','without any audience','in a dusty storage room'],'with brilliance or striking success','with éclat 表示出色而引人注目地。'),q('eclat',3,1,'Which event would bring a project eclat?',['a widely praised breakthrough','an unnoticed routine filing','a cancelled meeting with no outcome'],'a widely praised breakthrough','广受赞誉的突破带来盛誉与成功。'),q('eclat',4,1,'Eclat entered English from which language?',['French','Japanese','Swahili'],'French','eclat 来自法语 éclat。')]);

put('eclectic','eclectic 由希腊语 eklegein「挑选」相关词形发展而来，指从多种不同来源、流派或风格中选择并组合元素的。',c('eclectic.s1','室内设计','Her eclectic living room paired a modern steel lamp with a carved Indonesian chest and a woven rug from her grandmother’s village.','她的客厅兼收并蓄，把现代钢灯、印尼雕刻木箱和祖母家乡编织的地毯组合在一起。','Her eclectic living room paired a modern steel lamp / with a carved Indonesian chest / and a woven rug from her grandmother’s village.','eclectic 修饰 living room；并列家具来自不同地域、时代和风格。','将来源各异的设计元素组合，体现 eclectic.s1。'),'The designer called the room eclectic because every object came from one identical set and style.','The designer called the room eclectic because it combined objects from several distinct styles and sources.','全屋完全同一套风格并不体现从多种来源选取元素的 eclectic。',[q('eclectic',1,1,'An eclectic collection draws on?',['a wide range of different sources or styles','one source repeated without variation','items all made from the same material'],'a wide range of different sources or styles','eclectic.s1 指博采多种来源或风格。'),q('eclectic',2,1,'An eclectic playlist might include?',['classical strings, jazz, and folk songs','one identical song repeated all day','only silence'],'classical strings, jazz, and folk songs','不同流派并置构成 eclectic 歌单。'),q('eclectic',3,1,'Which room is most clearly eclectic?',['one mixing antique furniture, modern art, and woven textiles','one furnished entirely with matching pieces from a single set','an empty room with no objects'],'one mixing antique furniture, modern art, and woven textiles','多个时代与风格的家具混搭属于 eclectic。'),q('eclectic',4,1,'An eclectic approach to research would?',['select useful ideas from several schools of thought','follow one doctrine without considering alternatives','avoid reading any source'],'select useful ideas from several schools of thought','eclectic 方法会从不同理论中择取元素。')]);

put('eclecticism','eclecticism 由 eclectic 加名词后缀 -ism 构成，指有意从多个学派、理论或风格中择取并结合要素的方法。',c('eclecticism.s1','思想史','The architect’s eclecticism is apparent in a station that combines classical arches, local brickwork, and modernist glass without copying any one style completely.','这位建筑师的折中主义显现在一座车站中：古典拱门、本地砖艺与现代主义玻璃彼此结合，却没有完全照搬任何一种风格。','The architect’s eclecticism is apparent in a station / that combines classical arches / local brickwork / and modernist glass / without copying any one style completely.','eclecticism 是 is apparent in 的主语；that 从句列举从不同风格选取的元素。','多种建筑传统被有意识地组合，体现 eclecticism.s1。'),'The architect’s eclecticism meant rejecting every outside tradition and copying one style without change.','The architect’s eclecticism meant combining selected elements from several traditions.','拒绝所有其他传统、只照搬单一风格与 eclecticism 的多源折中方法相反。',[q('eclecticism',1,1,'Eclecticism is a method of?',['combining selected elements from several schools','following one doctrine exclusively','avoiding every influence'],'combining selected elements from several schools','eclecticism.s1 指综合多个流派或来源的方式。'),q('eclecticism',2,1,'A historian practising eclecticism might?',['draw useful concepts from different traditions','accept only one source and reject all others','stop comparing ideas'],'draw useful concepts from different traditions','折中主义会择取、结合不同传统的观念。'),q('eclecticism',3,1,'Which design philosophy shows eclecticism?',['blending local craft with modern and classical forms','reproducing one historical style in every detail','using no design influences whatsoever'],'blending local craft with modern and classical forms','混合多类风格要素体现 eclecticism。'),q('eclecticism',4,1,'Eclecticism differs from strict single-school adherence because it?',['selects and combines across schools','accepts only one school’s rules','rejects all methods of selection'],'selects and combines across schools','eclecticism 的特征是跨流派选取与整合。')]);

put('ecliptic','ecliptic 经由希腊语与日食、月食有关的词形形成；作名词指太阳在天球上的视运动路径，作形容词表示黄道的或与日食有关的。',c('ecliptic.s1','天文学观测','The observer marked the ecliptic across the star chart, then noted where the Moon crossed that apparent path during the coming month.','观测者在星图上标出黄道，随后记录月球在下个月何时穿过这条视路径。','The observer marked the ecliptic across the star chart / then noted where the Moon crossed that apparent path / during the coming month.','ecliptic 是 marked 的宾语；that apparent path 回指太阳视运动路径。','星图上的太阳周年视路径即 ecliptic.s1。'),'The astronomer drew the ecliptic as the path of a submarine moving below the ocean floor.','The astronomer drew the ecliptic as the Sun’s apparent path across the celestial sphere.','ecliptic 是天球上的太阳视运动路径，不是潜艇航线。',[q('ecliptic',1,1,'The ecliptic is the apparent path of the?',['Sun among the stars','Moon beneath the ocean','wind around a mountain'],'Sun among the stars','ecliptic.s1 指太阳在天球上的视路径。'),q('ecliptic',2,2,'An ecliptic coordinate is?',['related to the ecliptic','a measure of household income','a type of desert sand'],'related to the ecliptic','ecliptic.s2 是“黄道的、与黄道有关的”。'),q('ecliptic',3,1,'The Moon crosses the ecliptic when it?',['passes across the Sun’s apparent path','leaves the Earth’s atmosphere','moves through a forest'],'passes across the Sun’s apparent path','月球轨道与黄道相交时会穿越太阳视路径。'),q('ecliptic',4,1,'The ecliptic is an astronomical feature on the?',['celestial sphere','bottom of a household pipe','surface of a wooden canvas stand'],'celestial sphere','黄道是天球上的大圆，描述太阳视运动轨迹。')]);

put('ecological','ecological 由 ecology 加形容词后缀 -al 构成，指与生物及其环境的关系有关，也可指保护自然系统的。',c('ecological.s1','城市规划','The ecological survey found that the proposed road would divide a wetland used by migrating birds, so planners moved the route away from the marsh.','生态调查发现，拟建道路会切割候鸟使用的湿地，因此规划人员把路线移离沼泽。','The ecological survey found that the proposed road would divide a wetland / used by migrating birds / so planners moved the route away from the marsh.','ecological 修饰 survey；调查关注道路对生物及其栖息环境的影响。','评估道路对候鸟湿地的影响属于生态研究与环境保护。'),'The ecological survey ignored all living things and measured only the paint colour of office doors.','The ecological survey examined how the road might affect birds and their wetland habitat.','生物与栖息环境是 ecological 调查关心的对象，而不是办公室门色。',[q('ecological',1,1,'An ecological study concerns?',['relationships between living things and their environment','the spelling of legal documents','the height of a theatre stage'],'relationships between living things and their environment','ecological.s1 指生态学或自然系统方面的。'),q('ecological',2,1,'An ecological impact assessment might ask whether a road?',['disrupts wildlife habitat','changes the price of theatre tickets','improves a printer’s speed'],'disrupts wildlife habitat','道路对栖息地的影响属于生态评估。'),q('ecological',3,1,'Which is an ecological concern?',['loss of a wetland used by migrating birds','a missing label on an office drawer','the colour of a bus ticket'],'loss of a wetland used by migrating birds','湿地及其生物群落属于生态关注范围。'),q('ecological',4,1,'The adjective ecological is formed from ecology plus?',['-al','-less','-ward'],'-al','ecological 由 ecology 加形容词后缀 -al 构成。')]);

put('ecologically','ecologically 由 ecological 加副词后缀 -ly 构成，表示从生态角度看或以不损害自然系统的方式。',c('ecologically.s1','资源管理','The resort was planned ecologically: buildings were kept outside nesting areas, wastewater was treated, and visitors followed marked trails.','度假区按照生态原则规划：建筑避开筑巢区，废水经过处理，游客沿指定步道活动。','The resort was planned ecologically / buildings were kept outside nesting areas / wastewater was treated / and visitors followed marked trails.','ecologically 修饰 planned，说明规划遵循生态考虑；分号后列举具体做法。','保护筑巢地、处理废水并引导游客都体现生态方式。'),'The resort was planned ecologically by draining the wetland and destroying every nesting site.','The resort was planned ecologically by protecting nesting areas and treating its wastewater.','排干湿地、毁掉栖息地损害生态，不能称为 ecologically 规划。',[q('ecologically',1,1,'To manage a forest ecologically is to manage it?',['with regard to living systems and environmental effects','only to increase the number of roads','without considering plants or animals'],'with regard to living systems and environmental effects','ecologically.s1 表示从生态角度或按生态原则。'),q('ecologically',2,1,'Which resort choice is ecologically responsible?',['keeping construction away from nesting habitat','draining a wetland before birds arrive','dumping untreated wastewater into a stream'],'keeping construction away from nesting habitat','避免破坏栖息地属于生态友好规划。'),q('ecologically',3,1,'In “ecologically sensitive land,” ecologically relates to?',['the land’s living communities and environment','the land’s postal code','a building’s interior paint'],'the land’s living communities and environment','生态敏感性关乎生物群落和自然环境。'),q('ecologically',4,1,'The suffix -ly in ecologically makes the word an?',['adverb','plural noun','past-tense verb'],'adverb','-ly 将 ecological 变为方式副词 ecologically。')]);

put('ecologist','ecologist 由 ecology 加表示从业者的后缀 -ist 构成，指研究生物与栖息环境之间关系的科学家。',c('ecologist.s1','野外研究','The ecologist tagged several frogs and measured water quality to learn how a new farm drainage channel might affect the wetland population.','生态学家给几只青蛙做了标记并测量水质，以了解新的农田排水渠可能如何影响湿地种群。','The ecologist tagged several frogs and measured water quality / to learn how a new farm drainage channel might affect the wetland population.','ecologist 是 tagged 与 measured 的主语；to learn 表示开展调查的目的。','研究生物种群及其环境变化的人是 ecologist.s1。'),'The ecologist studied only the spelling of restaurant menus and never examined organisms or habitats.','The ecologist studied frogs, water conditions, and the wetland habitat.','生态学家研究生物及环境关系，不是只研究菜单拼写。',[q('ecologist',1,1,'An ecologist studies?',['relationships between organisms and their environment','the design of court robes','the manufacture of musical strings'],'relationships between organisms and their environment','ecologist.s1 指生态学研究者。'),q('ecologist',2,1,'Who should assess how a wetland change affects frogs and plants?',['an ecologist','a theatre usher','a piano tuner'],'an ecologist','栖息地变化对生物的影响属于生态学调查。'),q('ecologist',3,1,'An ecologist working in a forest might record?',['species, habitats, and environmental conditions','only the number of letters in tree names','the weight of a city bus'],'species, habitats, and environmental conditions','生态学家会观察物种、栖息地与环境条件。'),q('ecologist',4,1,'The ending -ist in ecologist often means?',['a person who studies or practises a field','a place without a field','a direction toward Earth'],'a person who studies or practises a field','-ist 常构成表示专业人员的名词。')]);

put('economically','economically 由 economic 加副词后缀 -ally 构成，可表示在经济或财务方面，也可表示节约地、不浪费资源地。',c('economically.s2','家庭能源','The insulation upgrade was economically installed in phases, allowing the landlord to reduce heating costs without replacing every window at once.','房东分阶段以节约成本的方式完成保温改造，降低了取暖费用，也不必一次更换所有窗户。','The insulation upgrade was economically installed in phases / allowing the landlord to reduce heating costs / without replacing every window at once.','economically 修饰 installed，表示节省资金、避免浪费；分阶段说明实施方式。','分阶段施工节省成本，体现 economically.s2。'),'The contractor worked economically by wasting materials and paying twice for every repair.','The contractor worked economically by reusing suitable materials and avoiding unnecessary costs.','浪费材料并重复付费与 economically“节约地”相反。',[q('economically',1,1,'A policy described economically may be discussed?',['in terms of money, trade, or a country’s economy','only in terms of an animal’s habitat','as a type of musical performance'],'in terms of money, trade, or a country’s economy','economically.s1 表示从经济或财务角度。'),q('economically',2,2,'To heat a home economically is to heat it?',['without wasting money or energy','at the highest possible cost','only by closing every room forever'],'without wasting money or energy','economically.s2 表示节约地、不浪费资源地。'),q('economically',3,1,'An economically important industry contributes to?',['jobs, trade, or national income','the shape of a planet’s orbit','a singer’s vocal range'],'jobs, trade, or national income','经济重要性与就业、贸易、收入有关。'),q('economically',4,2,'Which sentence uses economically to mean “without waste”?',['The team reused the equipment economically.','The economist analysed the policy economically.','The resort was ecologically planned.'],'The team reused the equipment economically.','此处 economically 修饰 reused，强调节约利用。')]);

put('economist','economist 由 economics/economy 加表示专业人员的 -ist 构成，指研究经济、市场或公共政策的专家。',c('economist.s1','公共政策','The economist compared wage data with housing costs before estimating how the proposed tax credit might affect low-income families.','这位经济学家先比较工资数据与住房成本，再估算拟议税收抵免可能如何影响低收入家庭。','The economist compared wage data with housing costs / before estimating how the proposed tax credit might affect low-income families.','economist 是 compared 与 estimating 的主语；before 表示分析和估算的先后。','分析工资、住房成本及税收政策影响属于经济学家工作。'),'The economist examined only sea-star anatomy and never considered markets, income, or policy.','The marine biologist examined sea-star anatomy; the economist analysed markets, income, and policy.','海星解剖属于生物学研究，不是经济学家的专业对象。',[q('economist',1,1,'An economist is an expert who studies?',['economics, markets, or economic policy','the construction of easels','the anatomy of sea stars only'],'economics, markets, or economic policy','economist.s1 指经济学研究者或专家。'),q('economist',2,1,'Which question is an economist most likely to analyse?',['How might a tax change affect employment and prices?','How do sea stars move their tube feet?','How can a violin string be tuned?'],'How might a tax change affect employment and prices?','税收对就业和价格的影响是经济分析问题。'),q('economist',3,1,'An economist using wage and housing data is studying?',['income and living costs','the ecliptic path of the Sun','a dune’s wind-blown shape'],'income and living costs','工资和住房费用是经济数据。'),q('economist',4,1,'The suffix -ist in economist identifies?',['a person associated with a field of study','an adjective meaning without money','a direction toward the economy'],'a person associated with a field of study','-ist 构成表示经济学专业人士的名词。')]);

put('ecotourism','ecotourism 由 eco-（生态、环境）与 tourism（旅游）构成，指尽量保护自然栖息地并支持当地社区的旅行活动。',c('ecotourism.s1','社区旅游','The ecotourism cooperative limits group sizes, hires local guides, and uses part of each booking fee to maintain trails and protect nesting beaches.','生态旅游合作社限制团队人数、聘用当地向导，并将部分预订费用用于维护步道和保护海龟筑巢海滩。','The ecotourism cooperative limits group sizes / hires local guides / and uses part of each booking fee / to maintain trails and protect nesting beaches.','ecotourism 修饰 cooperative；限流、雇用当地人和保护海滩体现旅游目标。','旅行活动同时顾及栖息地保护和社区收益，符合 ecotourism.s1。'),'The resort advertised ecotourism while destroying nesting beaches and excluding every local worker.','The resort practised ecotourism by limiting visitor impact and directing income toward local conservation.','破坏栖息地且排斥社区与生态旅游的保护、惠及当地目标相反。',[q('ecotourism',1,1,'Ecotourism aims to combine travel with?',['conservation and benefits for local communities','maximum habitat destruction','removing all local people from tourism'],'conservation and benefits for local communities','ecotourism.s1 指兼顾保护与社区的旅游。'),q('ecotourism',2,1,'Which practice best supports ecotourism?',['limiting visitors near a fragile nesting site','building a noisy resort across the habitat','leaving all waste beside a river'],'limiting visitors near a fragile nesting site','限制游客干扰有助于保护脆弱生态。'),q('ecotourism',3,1,'A local ecotourism guide can benefit a community by?',['earning income while sharing knowledge of the area','preventing residents from entering their village','replacing wildlife with traffic'],'earning income while sharing knowledge of the area','雇用当地向导能让旅游收益流入社区。'),q('ecotourism',4,1,'The prefix eco- in ecotourism points to?',['ecology and the natural environment','economics alone','an ancient musical instrument'],'ecology and the natural environment','eco- 与生态、自然环境有关。')]);

put('ecstasy','ecstasy 经拉丁语来自希腊语 ekstasis「出神、神魂超脱」，由 ek-「向外」和与“站立”有关的词根构成；现代常指极度喜悦。',c('ecstasy.s1','个人感受','When the final results confirmed her scholarship, Mei was in ecstasy, laughing and calling her family before she had even left the examination hall.','最终成绩确认她获得奖学金后，梅欣喜若狂，还没走出考场就笑着给家人打电话。','When the final results confirmed her scholarship / Mei was in ecstasy / laughing and calling her family / before she had even left the examination hall.','be in ecstasy 是“欣喜若狂”的搭配；后续动作显示强烈喜悦。','好消息使她极度快乐，符合 ecstasy.s1。'),'He felt ecstasy at the news and remained completely miserable, indifferent, and joyless.','He felt disappointment at the news and remained miserable and joyless.','极度喜悦与完全悲伤、毫不快乐相互矛盾。',[q('ecstasy',1,1,'Ecstasy is an intense feeling of?',['happiness or delight','mild annoyance','physical thirst only'],'happiness or delight','ecstasy.s1 指极度快乐、狂喜。'),q('ecstasy',2,1,'A fan might be in ecstasy when?',['her team wins a championship in the final second','she hears that nothing has changed','she is bored by an ordinary queue'],'her team wins a championship in the final second','重大胜利带来的强烈喜悦可称 ecstasy。'),q('ecstasy',3,1,'Which phrase is a natural use?',['be in ecstasy','make an ecstasy of the driveway','ecstasy the parcel by mail'],'be in ecstasy','be in ecstasy 是常见搭配。'),q('ecstasy',4,1,'The Greek source ekstasis originally suggested?',['standing outside oneself or being carried out of oneself','a stone wall by a river','a person who studies trade'],'standing outside oneself or being carried out of oneself','ecstasy 溯源至表示“出神、神魂超脱”的希腊词。')]);




})();
